 1→import { on } from '@ngrx/store';
 2→import { FavoritesActions } from '../actions';
 3→import { PlaylistState } from '../state';
 4→
 5→export const favoritesReducers = [
 6→    on(FavoritesActions.updateFavorites, (state, action): PlaylistState => {
 7→        let favorites;
 8→        const { channel } = action;
 9→        const playlistFavorites =
10→            state.playlists.entities[state.playlists.selectedId]?.favorites;
11→        if (playlistFavorites?.includes(channel.url)) {
12→            favorites = [
13→                ...(playlistFavorites ?? []).filter(
14→                    (url: string) => url !== channel.url
15→                ),
16→            ];
17→        } else {
18→            favorites = [...(playlistFavorites ?? []), channel.url];
19→        }
20→        return {
21→            ...state,
22→            playlists: {
23→                ...state.playlists,
24→                entities: {
25→                    ...state.playlists.entities,
26→                    [state.playlists.selectedId]: {
27→                        ...state.playlists.entities[state.playlists.selectedId],
28→                        favorites,
29→                    },
30→                },
31→            },
32→        };
33→    }),
34→    on(FavoritesActions.setFavorites, (state, action): PlaylistState => {
35→        const { channelIds } = action;
36→        return {
37→            ...state,
38→            playlists: {
39→                ...state.playlists,
40→                entities: {
41→                    ...state.playlists.entities,
42→                    [state.playlists.selectedId]: {
43→                        ...state.playlists.entities[state.playlists.selectedId],
44→                        favorites: channelIds,
45→                    },
46→                },
47→            },
48→        };
49→    }),
50→];
