 1→import { Injectable, signal } from '@angular/core';
 2→import { XtreamCategory } from 'shared-interfaces';
 3→
 4→/**
 5→ * Lightweight service that bridges the favorites/recently-viewed routed
 6→ * components (inside the router-outlet) with the WorkspaceShellComponent
 7→ * (the outer shell that renders the context panel aside).
 8→ *
 9→ * The routed component pushes its category list here via an effect;
10→ * the workspace shell reads it to populate the context panel.
11→ */
12→@Injectable({ providedIn: 'root' })
13→export class FavoritesContextService {
14→    /** Category list managed by the active routed component (Favorites / RecentlyViewed). */
15→    readonly categories = signal<XtreamCategory[]>([]);
16→
17→    /** Currently selected category id — shared between panel and content. */
18→    readonly selectedCategoryId = signal<string>('all');
19→
20→    /** Called by the context panel when the user clicks a category. */
21→    setCategoryId(id: string): void {
22→        this.selectedCategoryId.set(id);
23→    }
24→
25→    /** Called by the routed component to push its category list into the panel. */
26→    setCategories(categories: XtreamCategory[]): void {
27→        this.categories.set(categories);
28→    }
29→
30→    /** Reset to defaults when navigating away from favorites/recent sections. */
31→    reset(): void {
32→        this.categories.set([]);
33→        this.selectedCategoryId.set('all');
34→    }
35→}
