 1→import { inject } from '@angular/core';
 2→import {
 3→    patchState,
 4→    signalStoreFeature,
 5→    withMethods,
 6→    withState,
 7→} from '@ngrx/signals';
 8→import { DatabaseService } from 'services';
 9→import { FavoritesService } from './services/favorites.service';
10→import { createLogger } from '@iptvnator/portal/shared/util';
11→
12→export const withFavorites = function () {
13→    const logger = createLogger('withFavorites');
14→    return signalStoreFeature(
15→        withState({
16→            isFavorite: false,
17→        }),
18→        withMethods(
19→            (
20→                store,
21→                dbService = inject(DatabaseService),
22→                favoritesService = inject(FavoritesService)
23→            ) => ({
24→                async toggleFavorite(xtreamId: number, playlistId: string) {
25→                    if (!xtreamId || !playlistId) {
26→                        return false;
27→                    }
28→
29→                    // Get content by xtream ID
30→                    const content = await dbService.getContentByXtreamId(
31→                        xtreamId,
32→                        playlistId
33→                    );
34→                    if (!content) {
35→                        logger.error(
36→                            'Content not found for xtream ID',
37→                            xtreamId
38→                        );
39→                        return false;
40→                    }
41→
42→                    const currentStatus = store.isFavorite();
43→
44→                    if (currentStatus) {
45→                        // Remove from favorites
46→                        await favoritesService.removeFromFavorites(
47→                            content.id,
48→                            playlistId
49→                        );
50→                        patchState(store, { isFavorite: false });
51→                        return false;
52→                    } else {
53→                        // Add to favorites
54→                        await favoritesService.addToFavorites({
55→                            content_id: content.id,
56→                            playlist_id: playlistId,
57→                        });
58→                        patchState(store, { isFavorite: true });
59→                        return true;
60→                    }
61→                },
62→
63→                async checkFavoriteStatus(
64→                    xtreamId: number,
65→                    playlistId: string
66→                ) {
67→                    if (!xtreamId || !playlistId) {
68→                        patchState(store, { isFavorite: false });
69→                        return;
70→                    }
71→
72→                    // Get content by xtream ID
73→                    const content = await dbService.getContentByXtreamId(
74→                        xtreamId,
75→                        playlistId
76→                    );
77→                    if (!content) {
78→                        patchState(store, { isFavorite: false });
79→                        return;
80→                    }
81→
82→                    const isFavorite = await favoritesService.isFavorite(
83→                        content.id,
84→                        playlistId
85→                    );
86→
87→                    patchState(store, { isFavorite });
88→                },
89→            })
90→        )
91→    );
92→};
