21→    changeDetection: ChangeDetectionStrategy.OnPush,
22→    imports: [ChannelListItemComponent, TranslatePipe],
23→})
24→export class RecentViewComponent {
25→    readonly recentItems = input.required<RecentViewItem[]>();
26→    readonly channelEpgMap = input.required<Map<string, EpgProgram | null>>();
27→    readonly progressTick = input.required<number>();
28→    readonly shouldShowEpg = input.required<boolean>();
29→    readonly activeChannelUrl = input<string | undefined>();
30→
31→    readonly channelSelected = output<Channel>();
32→    readonly removeRecent = output<string>();
33→
34→    readonly enrichedRecentItems = computed(() => {
35→        const recentItems = this.recentItems();
36→        const epgMap = this.channelEpgMap();
37→        this.progressTick();
38→
39→        return recentItems.map(({ channel, viewedAt }) => {
40→            const channelId = channel?.tvg?.id?.trim() || channel?.name?.trim();
41→            const epgProgram = channelId ? epgMap.get(channelId) : null;
42→
43→            return {
44→                channel,
45→                viewedAt,
46→                epgProgram,
47→                progressPercentage: this.calculateProgress(epgProgram),
48→            };
49→        });
50→    });
51→
52→    private calculateProgress(
53→        epgProgram: EpgProgram | null | undefined
54→    ): number {
55→        if (!epgProgram) {
56→            return 0;
57→        }
58→
59→        const now = new Date().getTime();
60→        const start = new Date(epgProgram.start).getTime();
61→        const stop = new Date(epgProgram.stop).getTime();
62→        const total = stop - start;
63→        const elapsed = now - start;
64→
65→        return Math.min(100, Math.max(0, (elapsed / total) * 100));
66→    }
67→
68→    trackByFn(_: number, item: RecentViewItem): string {
69→        return item.channel?.url;
70→    }
71→
72→    onChannelClick(channel: Channel): void {
73→        this.channelSelected.emit(channel);
74→    }
75→
76→    onRemoveRecent(channel: Channel, event: MouseEvent): void {
77→        event.stopPropagation();
78→        this.removeRecent.emit(channel.url);
79→    }
80→}
