210→    constructor() {
211→        effect(() => {
212→            this.allFavorites.value();
213→            this.syncSelectedVodFavorite();
214→        });
215→
216→        effect(() => {
217→            const selectedCategoryId = this.selectedCategoryId();
218→            const hasInlineDetail = this.inlineDetail().categoryId !== null;
219→            const previousCategoryId = this.previousSelectedCategoryId;
220→
221→            this.previousSelectedCategoryId = selectedCategoryId;
222→
223→            if (
224→                hasInlineDetail &&
225→                previousCategoryId !== null &&
226→                previousCategoryId !== selectedCategoryId
227→            ) {
228→                this.resetDetailsView(false);
229→            }
230→        });
231→
232→        effect(() => {
233→            const selectedItem = this.selectedLiveItem();
234→            if (!selectedItem) {
235→                return;
236→            }
237→
238→            const stillExists = this.liveItemsToShow().some(
239→                (item) => normalizeStalkerEntityId(item.id) === normalizeStalkerEntityId(selectedItem.id)
240→            );
241→
242→            if (!stillExists) {
243→                this.clearLiveSelection();
244→            }
245→        });
246→
247→        effect(() => {
248→            if (this.isLiveCategory()) {
249→                return;
250→            }
251→
252→            this.clearLiveSelection();
253→        });
254→
255→        effect(() => {
256→            const playlist = this.currentPlaylist();
257→            if (!playlist?._id) {
258→                return;
259→            }
260→
261→            const state =
262→                this.router.currentNavigation()?.extras?.state ??
263→                window.history.state;
264→            const item = state?.openFavoriteItem;
265→            if (
266→                !item ||
267→                !StalkerFavoritesComponent.isCategoryType(item.category_id)
268→            ) {
269→                return;
270→            }
271→
272→            this.openItem(item);
273→
274→            try {
275→                window.history.replaceState({}, document.title);
276→            } catch {
277→                // no-op
278→            }
279→        });
280→    }
281→
282→    removeFromFavorites(
283→        item: Pick<StalkerFavoriteItem, 'id'>,
284→        onDone?: () => void
285→    ) {
286→        this.stalkerStore.removeFromFavorites(
287→            normalizeStalkerEntityId(item.id),
288→            () => {
289→                this.favoritesRefresh.refresh();
290→                this.syncSelectedVodFavorite();
291→                onDone?.();
292→            }
293→        );
294→    }
295→
296→    addToFavorites(item: Record<string, unknown>, onDone?: () => void) {
297→        this.stalkerStore.addToFavorites(item, () => {
298→            this.favoritesRefresh.refresh();
299→            this.syncSelectedVodFavorite();
300→            onDone?.();
301→        });
302→    }
303→
304→    setCategoryId(categoryId: string) {
305→        this.collectionContext.setCategoryId(categoryId);
306→    }
307→
308→    openItem(item: FavoriteLayoutItem) {
309→        this.logger.debug('Open item', item);
310→        const normalizedCategory =
311→            item.category_id === 'movie' ? 'vod' : item.category_id;
312→        const itemToOpen = {
313→            ...item,
314→            category_id: normalizedCategory,
315→        } as StalkerFavoriteItem;
316→        const normalizedItem = normalizeStalkerFavoriteItem(itemToOpen);
317→
318→        switch (itemToOpen.category_id) {
319→            case 'itv':
320→                this.setCategoryId('itv');
321→                this.resetDetailsView(false);
322→                void this.selectLiveItem(itemToOpen);
323→                break;
324→            case 'vod': {
325→                this.itemDetails = normalizedItem;
326→                this.stalkerStore.setSelectedItem(normalizedItem.details);
327→                this.stalkerStore.setSelectedContentType('vod');
328→
329→                const detailViewState = createStalkerDetailViewState(
330→                    normalizedItem.details,
331→                    this.currentPlaylist()?._id ?? ''
332→                );
333→                this.itemDetails = {
334→                    ...normalizedItem,
335→                    details: detailViewState.itemDetails,
336→                };
337→                this.vodDetailsItem = detailViewState.vodDetailsItem;
338→                this.syncSelectedVodFavorite();
339→                break;
340→            }
341→            case 'series':
342→                this.itemDetails = normalizedItem;
343→                this.stalkerStore.setSelectedItem(normalizedItem.details);
344→                this.stalkerStore.setSelectedContentType('series');
345→                break;
346→            default:
347→                break;
348→        }
349→    }
350→
351→    /** Handle play from vod-details component */
352→    onVodPlay(item: VodDetailsItem): void {
353→        if (item.type === 'stalker') {
354→            this.createLinkToPlayVodItv(
355→                item.cmd,
356→                item.data.info?.name,
357→                item.data.info?.movie_image
358→            );
359→        }
360→    }
361→
362→    /** Handle favorite toggle from vod-details component */
363→    onVodFavoriteToggled(event: {
364→        item: VodDetailsItem;
365→        isFavorite: boolean;
366→    }): void {
367→        toggleStalkerVodFavorite(event, {
368→            addToFavorites: (item, onDone) => this.addToFavorites(item, onDone),
369→            removeFromFavorites: (favoriteId, onDone) =>
370→                this.removeFromFavorites({ id: favoriteId }, onDone),
371→            onComplete: () => {
372→                this.favoritesRefresh.refresh();
373→                this.syncSelectedVodFavorite();
374→            },
375→        });
376→    }
377→
378→    /** Handle back from vod-details component */
379→    onVodBack(): void {
380→        this.resetDetailsView(true);
381→    }
382→
383→    onSeriesBack(): void {
384→        this.resetDetailsView(true);
385→    }
386→
387→    private resetDetailsView(refreshList: boolean): void {
388→        const cleared = clearStalkerDetailViewState();
389→        this.itemDetails = null;
390→        this.vodDetailsItem = cleared.vodDetailsItem;
391→        this.isSelectedVodFavorite.set(false);
392→        if (refreshList) {
393→            this.favoritesRefresh.refresh();
394→        }
395→    }
396→
397→    private syncSelectedVodFavorite(): void {
398→        this.isSelectedVodFavorite.set(
399→            isSelectedStalkerVodFavorite(
400→                this.vodDetailsItem,
401→                this.allFavorites.value() ?? []
402→            )
403→        );
404→    }
405→
406→    inlineDetail() {
407→        return createStalkerInlineDetailState(
408→            this.itemDetails,
409→            this.vodDetailsItem
410→        );
411→    }
412→
413→    showDetails() {
414→        return this.inlineDetail().categoryId !== null;
415→    }
416→
417→    async selectLiveItem(item: StalkerVodSource) {
418→        this.selectedLiveItem.set(item);
419→        this.liveStreamUrl.set('');
420→        this.stalkerStore.setSelectedContentType('itv');
421→        this.stalkerStore.setSelectedItem(item);
422→        this.isResolvingPlayback.set(true);
423→
424→        try {
425→            const playback = await this.stalkerStore.resolveItvPlayback(item);
426→            await this.loadEpgForChannel(item.id);
427→            this.liveStreamUrl.set(playback.streamUrl);
428→
429→            if (!this.isEmbeddedPlayer()) {
430→                void this.portalPlayer.openResolvedPlayback(playback, true);
431→            }
432→        } catch (error) {
433→            this.logger.error('Failed to resolve ITV playback', error);
434→            this.showPlaybackError(error);
435→        } finally {
436→            this.isResolvingPlayback.set(false);
437→        }
438→    }
439→
440→    async loadMoreEpg() {
441→        if (!this.epgChannelId || this.isLoadingEpg()) {
442→            return;
443→        }
444→
445→        this.epgPageSize += 10;
446→        this.isLoadingEpg.set(true);
447→        try {
448→            const items = await this.stalkerStore.fetchChannelEpg(
449→                this.epgChannelId,
450→                this.epgPageSize
451→            );
452→            this.epgItems.set(items);
453→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
454→        } catch {
455→            this.hasMoreEpg.set(false);
456→        } finally {
457→            this.isLoadingEpg.set(false);
458→        }
459→    }
460→
461→    async createLinkToPlayVodItv(
462→        cmd?: string,
463→        title?: string,
464→        thumbnail?: string
465→    ) {
466→        this.logger.debug('Create link to play VOD/ITV', {
467→            cmd,
468→            title,
469→            thumbnail,
470→        });
471→        await this.stalkerStore.createLinkToPlayVod(cmd, title, thumbnail);
472→    }
473→
474→    toggleLiveFavorite(item: StalkerVodSource): void {
475→        const itemId = normalizeStalkerEntityId(item.id);
476→        if (this.liveFavoriteIds().has(itemId)) {
477→            this.removeFromFavorites({ id: item.id });
478→            return;
479→        }
480→
481→        this.addToFavorites({
482→            ...item,
483→            category_id: 'itv',
484→            title: item.o_name || item.name,
485→            cover: item.logo,
486→            added_at: new Date().toISOString(),
487→        });
488→    }
489→
490→    readonly liveFavoriteIds = computed(() => {
491→        const ids = new Map<string | number, boolean>();
492→        for (const item of this.liveItemsToShow()) {
493→            ids.set(normalizeStalkerEntityId(item.id), true);
494→        }
495→        return ids;
496→    });
497→
498→    private clearLiveSelection() {
499→        this.selectedLiveItem.set(null);
500→        this.liveStreamUrl.set('');
501→        this.isResolvingPlayback.set(false);
502→        this.epgItems.set([]);
503→        this.isLoadingEpg.set(false);
504→        this.hasMoreEpg.set(false);
505→        this.epgChannelId = null;
506→        this.stalkerStore.setSelectedItem(null);
507→    }
508→
509→    private async loadEpgForChannel(channelId: number | string | undefined) {
510→        if (channelId === undefined || channelId === null) {
511→            this.epgItems.set([]);
512→            this.hasMoreEpg.set(false);
513→            return;
514→        }
515→
516→        this.epgChannelId = channelId;
517→        this.epgPageSize = 10;
518→        this.isLoadingEpg.set(true);
519→        this.epgItems.set([]);
520→        this.hasMoreEpg.set(false);
521→
522→        try {
523→            const items = await this.stalkerStore.fetchChannelEpg(
524→                channelId,
525→                this.epgPageSize
526→            );
527→            this.epgItems.set(items);
528→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
529→        } catch {
530→            this.epgItems.set([]);
531→        } finally {
532→            this.isLoadingEpg.set(false);
533→        }
534→    }
535→
536→    private showPlaybackError(error: unknown): void {
537→        const errorMessage =
538→            error instanceof Error && error.message === 'nothing_to_play'
539→                ? this.translate.instant('PORTALS.CONTENT_NOT_AVAILABLE')
540→                : this.translate.instant('PORTALS.PLAYBACK_ERROR');
541→        this.snackBar.open(errorMessage, undefined, { duration: 3000 });
542→    }
543→}
