169→        );
170→        if (!saved) {
171→            return signal({ live: true, movie: true, series: true });
172→        }
173→        try {
174→            const parsed = JSON.parse(saved) as {
175→                live?: boolean;
176→                movie?: boolean;
177→                series?: boolean;
178→            };
179→            return signal({
180→                live: parsed.live !== false,
181→                movie: parsed.movie !== false,
182→                series: parsed.series !== false,
183→            });
184→        } catch {
185→            return signal({ live: true, movie: true, series: true });
186→        }
