189→    readonly recentItems = computed<XtreamRecentViewItem[]>(() =>
190→        (this.isGlobal
191→            ? this.xtreamStore.globalRecentItems()
192→            : this.xtreamStore.recentItems()) as XtreamRecentViewItem[]
