211→    readonly collectionContext = createPortalCollectionContext({
212→        ctx: this.favoritesCtx,
213→        categories: this.categories,
214→        enabled: () => !this.isGlobal,
215→    });
216→    readonly selectedLiveItem = signal<XtreamRecentLiveItem | null>(null);
217→    readonly liveStreamUrl = signal('');
218→    readonly nonGlobalMode = computed<PortalCollectionMode>(() =>
219→        this.isLiveCategory() ? 'live' : 'grid'
220→    );
221→    readonly selectedCategoryId = this.collectionContext.selectedCategoryId;
222→    readonly recentSearchTerm = signal('');
223→    readonly workspaceSearchTerm = queryParamSignal(
224→        this.activatedRoute,
225→        'q',
226→        (value) => (value ?? '').trim().toLowerCase()
227→    );
228→    readonly filteredRecentItems = computed(() => {
229→        const term =
230→            this.isWorkspaceLayout && !this.isGlobal
231→                ? this.workspaceSearchTerm()
232→                : this.recentSearchTerm().trim().toLowerCase();
233→        const typeFilters = this.typeFilters();
234→        const items = this.recentItems().filter((item) => {
235→            if (item.type === 'live') return typeFilters.live;
236→            if (item.type === 'movie') return typeFilters.movie;
