468→    async onRemoveItem(item: FavoriteLayoutItem) {
469→        if (!isXtreamRecentViewItem(item)) {
470→            return;
471→        }
472→
473→        try {
474→            if (this.isGlobal) {
475→                if (item.source === 'stalker') {
476→                    await firstValueFrom(
477→                        this.playlistsService.removeFromPortalRecentlyViewed(
478→                            item.playlist_id,
479→                            item.id
480→                        )
481→                    );
482→                } else if (item.source === 'm3u') {
483→                    await firstValueFrom(
484→                        this.playlistsService.removeFromM3uRecentlyViewed(
485→                            item.playlist_id,
486→                            String(item.xtream_id ?? item.id)
487→                        )
488→                    );
489→                } else {
490→                    await this.dbService.removeRecentItem(
491→                        Number(item.id),
492→                        item.playlist_id
493→                    );
494→                }
495→                await this.loadGlobalItems();
496→                return;
497→            }
498→
499→            const playlist = this.currentPlaylist();
500→            if (!playlist) {
501→                return;
502→            }
503→
504→            this.xtreamStore.removeRecentItem({
505→                itemId: Number(item.id),
506→                playlistId: playlist.id,
507→            });
508→        } catch (error) {
509→            this.logger.error('Error removing recent item', error);
510→        }
511→    }
512→
513→    getGroupedItems() {
514→        const items = this.visibleRecentItems();
515→        if (!this.isGlobal) return { default: items };
516→        return groupItemsByPlaylistName(items);
517→    }
