529→    }
530→
531→    toggleTypeFilter(type: 'live' | 'movie' | 'series', value: boolean) {
532→        const next = {
533→            ...this._typeFilters(),
534→            [type]: value,
535→        };
536→        this._typeFilters.set(next);
537→        localStorage.setItem(
538→            RecentlyViewedComponent.TYPE_FILTERS_STORAGE_KEY,
539→            JSON.stringify(next)
540→        );
541→    }
542→
543→    setCategoryId(categoryId: string): void {
544→        this.collectionContext.setCategoryId(categoryId);
545→    }
546→
547→    selectLiveItem(item: XtreamRecentLiveItem): void {
548→        this.xtreamStore.setSelectedContentType('live');
549→        this.selectedLiveItem.set(item);
550→        const streamUrl = this.xtreamStore.constructStreamUrl(item);
551→        this.liveStreamUrl.set(streamUrl);
552→
553→        if (this.isEmbeddedPlayer()) {
554→            return;
555→        }
556→
557→        this.xtreamStore.openPlayer(
558→            streamUrl,
559→            item.title,
560→            item.poster_url || item.stream_icon || null
561→        );
562→    }
563→
564→    setLiveChannelSortMode(mode: LiveChannelSortMode): void {
565→        this.liveChannelSortMode.set(mode);
566→        localStorage.setItem(XTREAM_RECENT_LIVE_SORT_STORAGE_KEY, mode);
567→    }
