362→                );
363→                const detailViewState = createStalkerDetailViewState(
364→                    normalizedItem,
365→                    this.currentPlaylist()?._id ?? ''
366→                );
367→                this.itemDetails = {
368→                    ...(detailViewState.itemDetails ?? normalizedItem),
369→                    category_id: 'vod',
370→                };
371→                this.vodDetailsItem = detailViewState.vodDetailsItem;
372→                this.stalkerStore.setSelectedItem(detailViewState.itemDetails);
373→                this.syncSelectedVodFavorite();
374→                break;
375→            }
376→            case 'series':
377→                this.itemDetails = this.normalizeRecentItem(
378→                    item as StalkerVodSource & { category_id: string }
379→                );
380→                this.stalkerStore.setSelectedItem(this.itemDetails);
381→                break;
382→            default:
383→                break;
384→        }
385→    }
386→
387→    /** Handle play from vod-details component */
388→    onVodPlay(item: VodDetailsItem): void {
389→        if (item.type === 'stalker') {
390→            this.createLinkToPlayVodItv(
391→                item.cmd,
392→                item.data.info?.name,
393→                item.data.info?.movie_image
394→            );
395→        }
396→    }
397→
398→    /** Handle favorite toggle from vod-details component */
399→    onVodFavoriteToggled(event: {
400→        item: VodDetailsItem;
401→        isFavorite: boolean;
402→    }): void {
403→        toggleStalkerVodFavorite(event, {
404→            addToFavorites: (item, onDone) => this.addToFavorites(item, onDone),
405→            removeFromFavorites: (favoriteId, onDone) =>
406→                this.removeFromFavorites(favoriteId, onDone),
407→            onComplete: () => {
408→                this.favoritesRefresh.refresh();
409→                this.syncSelectedVodFavorite();
410→            },
411→        });
412→    }
413→
414→    /** Handle back from vod-details component */
415→    onVodBack(): void {
416→        this.clearDetailsView();
417→    }
418→
419→    async selectLiveItem(item: StalkerVodSource) {
420→        this.selectedLiveItem.set(item);
421→        this.liveStreamUrl.set('');
422→        this.stalkerStore.setSelectedContentType('itv');
423→        this.stalkerStore.setSelectedItem(item);
424→        this.isResolvingPlayback.set(true);
425→
426→        try {
427→            const playback = await this.stalkerStore.resolveItvPlayback(item);
428→            await this.loadEpgForChannel(item.id);
429→            this.liveStreamUrl.set(playback.streamUrl);
430→
431→            if (!this.isEmbeddedPlayer()) {
432→                void this.portalPlayer.openResolvedPlayback(playback, true);
433→            }
434→        } catch (error) {
435→            this.logger.error('Failed to resolve ITV playback', error);
436→            this.showPlaybackError(error);
437→        } finally {
438→            this.isResolvingPlayback.set(false);
439→        }
440→    }
441→
442→    async loadMoreEpg() {
443→        if (!this.epgChannelId || this.isLoadingEpg()) {
444→            return;
445→        }
446→
447→        this.epgPageSize += 10;
448→        this.isLoadingEpg.set(true);
449→        try {
450→            const items = await this.stalkerStore.fetchChannelEpg(
451→                this.epgChannelId,
452→                this.epgPageSize
453→            );
454→            this.epgItems.set(items);
455→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
456→        } catch {
457→            this.hasMoreEpg.set(false);
458→        } finally {
459→            this.isLoadingEpg.set(false);
460→        }
461→    }
462→
463→    async createLinkToPlayVodItv(
464→        cmd?: string,
465→        title?: string,
466→        thumbnail?: string
467→    ) {
468→        this.logger.debug('Create link to play VOD/ITV', {
469→            cmd,
470→            title,
471→            thumbnail,
472→        });
473→        await this.stalkerStore.createLinkToPlayVod(cmd, title, thumbnail);
474→    }
475→
476→    addToFavorites(item: Record<string, unknown>, onDone?: () => void) {
477→        this.stalkerStore.addToFavorites(item, onDone);
478→    }
479→
480→    removeFromFavorites(favoriteId: string, onDone?: () => void) {
481→        this.stalkerStore.removeFromFavorites(favoriteId, onDone);
482→    }
483→
484→    toggleLiveFavorite(item: StalkerVodSource): void {
485→        const itemId = String(item.id ?? '');
486→        if (this.liveFavoriteIds().has(itemId)) {
487→            this.removeFromFavorites(itemId);
488→            return;
489→        }
490→
491→        this.addToFavorites({
492→            ...item,
493→            category_id: 'itv',
494→            title: item.o_name || item.name,
495→            cover: item.logo || item.cover,
496→            added_at: new Date().toISOString(),
497→        });
498→    }
499→
500→    readonly liveFavoriteIds = computed(() => {
501→        const ids = new Map<string | number, boolean>();
502→        for (const item of (this.portalFavorites.value() ?? []) as StalkerVodSource[]) {
503→            if (item.category_id === 'itv') {
504→                ids.set(String(item.id ?? ''), true);
505→            }
506→        }
507→        return ids;
508→    });
509→
510→    private clearLiveSelection() {
511→        this.selectedLiveItem.set(null);
512→        this.liveStreamUrl.set('');
513→        this.isResolvingPlayback.set(false);
514→        this.epgItems.set([]);
515→        this.isLoadingEpg.set(false);
516→        this.hasMoreEpg.set(false);
517→        this.epgChannelId = null;
518→        this.stalkerStore.setSelectedItem(null);
519→    }
520→
521→    /**
522→     * Normalize recent item to ensure is_series flag is properly set
523→     * and all required fields are present for the series view
524→     */
525→    private normalizeRecentItem(
526→        item: StalkerVodSource
527→    ): StalkerSelectedVodItem {
528→        return normalizeStalkerVodDetailsItem(item);
529→    }
530→
531→    private syncSelectedVodFavorite(): void {
532→        this.isSelectedVodFavorite.set(
533→            isSelectedStalkerVodFavorite(
534→                this.vodDetailsItem,
535→                this.portalFavorites.value() ?? []
536→            )
537→        );
538→    }
539→
540→    private clearDetailsView(): void {
541→        const cleared = clearStalkerDetailViewState();
542→        this.itemDetails = cleared.itemDetails;
543→        this.vodDetailsItem = cleared.vodDetailsItem;
544→        this.isSelectedVodFavorite.set(false);
545→    }
546→
547→    inlineDetail() {
548→        return createStalkerInlineDetailState(
549→            this.itemDetails,
550→            this.vodDetailsItem
551→        );
552→    }
553→
554→    showDetails() {
555→        return this.inlineDetail().categoryId !== null;
556→    }
557→
558→    private async loadEpgForChannel(channelId: number | string | undefined) {
559→        if (channelId === undefined || channelId === null) {
560→            this.epgItems.set([]);
561→            this.hasMoreEpg.set(false);
562→            return;
563→        }
564→
565→        this.epgChannelId = channelId;
566→        this.epgPageSize = 10;
567→        this.isLoadingEpg.set(true);
568→        this.epgItems.set([]);
569→        this.hasMoreEpg.set(false);
570→
571→        try {
572→            const items = await this.stalkerStore.fetchChannelEpg(
573→                channelId,
574→                this.epgPageSize
575→            );
576→            this.epgItems.set(items);
577→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
578→        } catch {
579→            this.epgItems.set([]);
580→        } finally {
581→            this.isLoadingEpg.set(false);
582→        }
583→    }
584→
585→    private showPlaybackError(error: unknown): void {
586→        const errorMessage =
587→            error instanceof Error && error.message === 'nothing_to_play'
588→                ? this.translate.instant('PORTALS.CONTENT_NOT_AVAILABLE')
589→                : this.translate.instant('PORTALS.PLAYBACK_ERROR');
590→        this.snackBar.open(errorMessage, undefined, { duration: 3000 });
591→    }
592→}
