  6→    OnInit,
  7→    signal,
  8→} from '@angular/core';
  9→import { MatButtonModule } from '@angular/material/button';
 10→import { MatIconModule } from '@angular/material/icon';
 11→import { MatMenuModule } from '@angular/material/menu';
 12→import { MatTooltipModule } from '@angular/material/tooltip';
 13→import { ActivatedRoute, Router } from '@angular/router';
 14→import { Store } from '@ngrx/store';
 15→import { TranslatePipe } from '@ngx-translate/core';
 16→import { selectActivePlaylist } from 'm3u-state';
 17→import { BehaviorSubject, switchMap } from 'rxjs';
 18→import { PortalCollectionLiveShellComponent } from '@iptvnator/portal/shared/ui';
 19→import {
 20→    FavoriteLayoutItem,
 21→    PortalCollectionMode,
 22→    PortalCollectionShellComponent,
 23→    PortalCollectionShellLayout,
 24→} from '@iptvnator/portal/shared/ui';
 25→import {
 26→    buildStandardCollectionCategories,
 27→    createPortalCollectionContext,
 28→    filterCollectionBucket,
 29→    PORTAL_PLAYER,
 30→    queryParamSignal,
 31→} from '@iptvnator/portal/shared/util';
 32→import { FavoritesContextService } from '@iptvnator/portal/shared/util';
 33→import { PortalChannelsListComponent } from '../portal-channels-list/portal-channels-list.component';
 34→import { FavoriteItem } from '@iptvnator/portal/xtream/data-access';
 35→import { FavoritesService } from '@iptvnator/portal/xtream/data-access';
 36→import { XtreamStore } from '@iptvnator/portal/xtream/data-access';
 37→
 38→const XTREAM_FAVORITES_LAYOUT: PortalCollectionShellLayout = {};
 39→const XTREAM_COLLECTION_LABELS = {
 40→    all: 'All',
 41→    movie: 'Movies',
 42→    live: 'Live TV',
 43→    series: 'Series',
 44→};
 45→type LiveChannelSortMode = 'server' | 'name-asc' | 'name-desc';
 46→const XTREAM_FAVORITES_LIVE_SORT_STORAGE_KEY =
 47→    'xtream-favorites-live-channel-sort-mode';
 48→
 49→interface XtreamFavoriteLiveItem {
 50→    readonly poster_url?: string;
 51→    readonly stream_icon?: string;
 52→    readonly title?: string;
 53→    readonly xtream_id: number;
 54→}
 55→
 56→interface XtreamFavoriteRouteItem extends FavoriteLayoutItem {
 57→    readonly content_id: number;
 58→    readonly category_id: string | number;
 59→    readonly playlist_id: string;
 60→    readonly title: string;
 61→    readonly type: FavoriteItem['type'];
 62→    readonly xtream_id: number;
 63→}
 64→
 65→function isXtreamFavoriteRouteItem(
 66→    item: FavoriteLayoutItem
 67→): item is XtreamFavoriteRouteItem {
 68→    return (
 69→        typeof item.content_id === 'number' &&
 70→        item.category_id != null &&
 71→        typeof item.playlist_id === 'string' &&
 72→        typeof item.title === 'string' &&
 73→        typeof item.xtream_id === 'number' &&
 74→        typeof item.type === 'string'
 75→    );
 76→}
