 25→export class FavoritesViewComponent {
 26→    /** Favorite channels */
 27→    readonly favorites = input.required<Channel[]>();
 28→
 29→    /** EPG map for channel enrichment */
 30→    readonly channelEpgMap = input.required<Map<string, EpgProgram | null>>();
 31→
 32→    /** Progress tick to trigger progress recalculation */
 33→    readonly progressTick = input.required<number>();
 34→
 35→    /** Whether to show EPG data */
 36→    readonly shouldShowEpg = input.required<boolean>();
 37→
 38→    /** Currently active channel URL */
 39→    readonly activeChannelUrl = input<string | undefined>();
 40→
 41→    /** Emits when a channel is selected */
 42→    readonly channelSelected = output<Channel>();
 43→
 44→    /** Emits when favorite is toggled (removed) */
 45→    readonly favoriteToggled = output<{
 46→        channel: Channel;
 47→        event: MouseEvent;
 48→    }>();
 49→
 50→    /** Emits when favorites order changes via drag-drop */
 51→    readonly favoritesReordered = output<string[]>();
 52→
 53→    /**
 54→     * Computed signal for enriched favorites with EPG data
 55→     */
 56→    readonly enrichedFavorites = computed(() => {
 57→        const favorites = this.favorites();
 58→        const epgMap = this.channelEpgMap();
 59→        // Read progressTick to trigger recalculation
 60→        this.progressTick();
 61→
 62→        return favorites.map((channel) => {
 63→            const channelId = channel?.tvg?.id?.trim() || channel?.name?.trim();
 64→            const epgProgram = channelId ? epgMap.get(channelId) : null;
 65→            return {
 66→                ...channel,
 67→                epgProgram,
 68→                progressPercentage: this.calculateProgress(epgProgram),
 69→            } as EnrichedChannel;
 70→        });
 71→    });
 72→
 73→    /**
 74→     * Calculates progress percentage for an EPG program
 75→     */
 76→    private calculateProgress(
 77→        epgProgram: EpgProgram | null | undefined
 78→    ): number {
 79→        if (!epgProgram) {
 80→            return 0;
 81→        }
 82→
 83→        const now = new Date().getTime();
 84→        const start = new Date(epgProgram.start).getTime();
 85→        const stop = new Date(epgProgram.stop).getTime();
 86→
 87→        const total = stop - start;
 88→        const elapsed = now - start;
 89→
 90→        return Math.min(100, Math.max(0, (elapsed / total) * 100));
 91→    }
 92→
 93→    trackByFn(_: number, channel: Channel): string {
 94→        return channel?.id;
 95→    }
 96→
 97→    onChannelClick(channel: Channel): void {
 98→        this.channelSelected.emit(channel);
 99→    }
100→
101→    onFavoriteToggle(channel: Channel, event: MouseEvent): void {
102→        this.favoriteToggled.emit({ channel, event });
103→    }
104→
105→    onDrop(event: CdkDragDrop<Channel[]>): void {
106→        const favorites = [...this.favorites()];
107→        moveItemInArray(favorites, event.previousIndex, event.currentIndex);
108→        this.favoritesReordered.emit(favorites.map((item) => item.url));
109→    }
110→}
