385→
386→    openItem(item: FavoriteLayoutItem) {
387→        if (!isXtreamRecentViewItem(item)) {
388→            return;
389→        }
390→
391→        const source = item.source ?? 'xtream';
392→
393→        if (source === 'stalker' && this.isGlobal) {
394→            this.dialogRef?.close();
395→            this.router.navigate(
396→                ['/workspace', 'stalker', item.playlist_id, 'recent'],
397→                {
398→                    state: {
399→                        openRecentItem: item.stalker_item ?? {
400→                            id: item.id,
401→                            title: item.title,
402→                            name: item.title,
403→                            category_id:
404→                                item.type === 'movie'
405→                                    ? 'vod'
406→                                    : item.type === 'live'
407→                                      ? 'itv'
408→                                      : 'series',
409→                            cover: item.poster_url,
410→                        },
411→                    },
412→                }
413→            );
414→            return;
415→        }
416→
417→        if (source === 'm3u' && this.isGlobal) {
418→            this.dialogRef?.close();
419→            this.router.navigate(
420→                ['/workspace', 'playlists', item.playlist_id, 'recent'],
421→                {
422→                    state: {
423→                        openRecentChannelUrl: String(
424→                            item.xtream_id ?? item.id ?? ''
425→                        ),
426→                    },
427→                }
428→            );
429→            return;
430→        }
431→
432→        const type = item.type === 'movie' ? 'vod' : item.type;
433→        this.xtreamStore.setSelectedContentType(type);
434→
435→        if (!this.isGlobal && type === 'live') {
436→            this.setCategoryId('live');
437→            this.selectLiveItem({
438→                id: item.id,
439→                poster_url: item.poster_url,
440→                stream_icon: item.stream_icon,
441→                title: item.title,
442→                xtream_id: Number(item.xtream_id),
443→            });
444→            return;
445→        }
446→
447→        if (this.isGlobal) {
448→            this.dialogRef?.close();
449→
450→            this.router.navigate([
451→                '/workspace',
452→                'xtreams',
453→                item.playlist_id,
454→                type,
455→                item.category_id,
456→                item.xtream_id,
457→            ]);
458→        } else {
459→            this.router.navigate(
460→                ['..', type, item.category_id, item.xtream_id],
461→                {
462→                    relativeTo: this.activatedRoute,
463→                }
464→            );
465→        }
