468→    async onRemoveItem(item: FavoriteLayoutItem) {
469→        if (!isXtreamRecentViewItem(item)) {
470→            return;
471→        }
472→
473→        try {
474→            if (this.isGlobal) {
475→                if (item.source === 'stalker') {
476→                    await firstValueFrom(
477→                        this.playlistsService.removeFromPortalRecentlyViewed(
478→                            item.playlist_id,
479→                            item.id
480→                        )
