 20→/**
 21→ * Favorites concern methods.
 22→ */
 23→export function withStalkerFavorites() {
 24→    return signalStoreFeature(
 25→        withMethods(
 26→            (
 27→                store,
 28→                playlistService = inject(PlaylistsService),
 29→                snackBar = inject(MatSnackBar),
 30→                translate = inject(TranslateService),
 31→                ngrxStore = inject(Store)
 32→            ) => {
 33→                const storeContext = store as unknown as FavoritesStoreContext;
 34→                return {
 35→                    addToFavorites(item: FavoritePayload, onDone?: () => void) {
 36→                        const portalId = storeContext.currentPlaylist()?._id;
 37→                        playlistService
 38→                            .addPortalFavorite(portalId, {
 39→                                ...item,
 40→                                category_id: storeContext.selectedContentType(),
 41→                                added_at: Date.now(),
 42→                                id: item.stream_id ?? item.id,
 43→                            })
 44→                            .subscribe((updatedPlaylist) => {
 45→                                ngrxStore.dispatch(
 46→                                    PlaylistActions.updatePlaylistMeta({
 47→                                        playlist: {
 48→                                            _id: portalId,
 49→                                            favorites:
 50→                                                updatedPlaylist?.favorites,
 51→                                        } as PlaylistMeta,
 52→                                    })
 53→                                );
 54→                                snackBar.open(
 55→                                    translate.instant(
 56→                                        'PORTALS.ADDED_TO_FAVORITES'
 57→                                    ),
 58→                                    null,
 59→                                    {
 60→                                        duration: 1000,
 61→                                    }
 62→                                );
 63→                                onDone?.();
 64→                            });
 65→                    },
 66→                    removeFromFavorites(
 67→                        favoriteId: string,
 68→                        onDone?: () => void
 69→                    ) {
