 85→                                        'PORTALS.REMOVED_FROM_FAVORITES'
 86→                                    ),
 87→                                    null,
 88→                                    {
 89→                                        duration: 1000,
 90→                                    }
 91→                                );
 92→                                onDone?.();
 93→                            });
 94→                    },
 95→                };
 96→            }
