311→            item.category_id === 'movie' ? 'vod' : item.category_id;
312→        const itemToOpen = {
313→            ...item,
314→            category_id: normalizedCategory,
315→        } as StalkerFavoriteItem;
316→        const normalizedItem = normalizeStalkerFavoriteItem(itemToOpen);
317→
318→        switch (itemToOpen.category_id) {
