417→    async selectLiveItem(item: StalkerVodSource) {
418→        this.selectedLiveItem.set(item);
419→        this.liveStreamUrl.set('');
420→        this.stalkerStore.setSelectedContentType('itv');
421→        this.stalkerStore.setSelectedItem(item);
422→        this.isResolvingPlayback.set(true);
423→
424→        try {
425→            const playback = await this.stalkerStore.resolveItvPlayback(item);
426→            await this.loadEpgForChannel(item.id);
427→            this.liveStreamUrl.set(playback.streamUrl);
428→
429→            if (!this.isEmbeddedPlayer()) {
430→                void this.portalPlayer.openResolvedPlayback(playback, true);
431→            }
432→        } catch (error) {
433→            this.logger.error('Failed to resolve ITV playback', error);
434→            this.showPlaybackError(error);
435→        } finally {
436→            this.isResolvingPlayback.set(false);
437→        }
438→    }
439→
440→    async loadMoreEpg() {
441→        if (!this.epgChannelId || this.isLoadingEpg()) {
442→            return;
443→        }
444→
445→        this.epgPageSize += 10;
446→        this.isLoadingEpg.set(true);
447→        try {
448→            const items = await this.stalkerStore.fetchChannelEpg(
449→                this.epgChannelId,
450→                this.epgPageSize
451→            );
452→            this.epgItems.set(items);
453→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
454→        } catch {
455→            this.hasMoreEpg.set(false);
456→        } finally {
457→            this.isLoadingEpg.set(false);
458→        }
459→    }
