 1→import {
 2→    ChangeDetectionStrategy,
 3→    Component,
 4→    effect,
 5→    ElementRef,
 6→    inject,
 7→    input,
 8→    output,
 9→} from '@angular/core';
10→import { MatListModule } from '@angular/material/list';
11→import { TranslatePipe } from '@ngx-translate/core';
12→import { PlaylistErrorViewComponent } from '../playlist-error-view/playlist-error-view.component';
13→
14→interface CategoryViewItem {
15→    readonly category_id?: string | number;
16→    readonly category_name?: string;
17→    readonly count?: number;
18→    readonly id?: string | number;
19→    readonly name?: string;
20→}
21→
22→@Component({
23→    selector: 'app-category-view',
24→    imports: [MatListModule, PlaylistErrorViewComponent, TranslatePipe],
25→    changeDetection: ChangeDetectionStrategy.OnPush,
26→    templateUrl: './category-view.component.html',
27→    styleUrls: ['./category-view.component.scss'],
28→})
29→export class CategoryViewComponent {
30→    readonly items = input<CategoryViewItem[]>([]);
31→    readonly selectedCategoryId = input<string | number | null | undefined>();
32→    readonly itemCounts = input<Map<number, number>>(new Map());
33→    readonly showCounts = input<boolean>(false);
34→    private readonly hostEl = inject(ElementRef<HTMLElement>);
35→
36→    readonly categoryClicked = output<CategoryViewItem>();
37→
38→    constructor() {
39→        effect(() => {
40→            const selectedCategory = this.selectedCategoryId();
41→            if (selectedCategory == null) return;
42→
43→            queueMicrotask(() => {
44→                const container = this.hostEl.nativeElement as HTMLElement;
45→                const candidates = Array.from(
46→                    container.querySelectorAll('[data-category-id]')
47→                ) as HTMLElement[];
48→                const selected = candidates.find(
49→                    (el) => el.dataset.categoryId === String(selectedCategory)
50→                );
51→                selected?.scrollIntoView({
52→                    behavior: 'smooth',
53→                    block: 'nearest',
54→                    inline: 'nearest',
55→                });
56→            });
57→        });
58→    }
59→
60→    isSelected(item: CategoryViewItem): boolean {
61→        const selectedCategory = this.selectedCategoryId();
62→        const itemId = item.category_id ?? item.id;
63→
64→        // Compare as strings to handle both numeric and string category IDs.
65→        return (
66→            selectedCategory != null &&
67→            String(selectedCategory) === String(itemId)
68→        );
69→    }
70→
71→    getItemCount(item: CategoryViewItem): number {
72→        // content.category_id references categories.id (internal DB id)
73→        // For DB format categories, use id; for API format, use category_id
74→        const itemId = Number(item.id ?? item.category_id);
75→        return this.itemCounts().get(itemId) ?? 0;
76→    }
77→}
