 1→import { inject } from '@angular/core';
 2→import { signalStoreFeature, withMethods } from '@ngrx/signals';
 3→import { Store } from '@ngrx/store';
 4→import { PlaylistActions } from 'm3u-state';
 5→import { PlaylistsService } from 'services';
 6→import { PlaylistMeta, StalkerPortalItem } from 'shared-interfaces';
 7→import { createLogger } from '@iptvnator/portal/shared/util';
 8→
 9→interface RecentStoreContext {
10→    currentPlaylist(): PlaylistMeta | undefined;
11→    selectedContentType(): string;
12→}
13→
14→type RecentlyViewedPayload = StalkerPortalItem & {
15→    id?: string | number;
16→    title?: string;
17→};
18→
19→/**
20→ * Recently-viewed concern methods.
21→ */
22→export function withStalkerRecent() {
23→    const logger = createLogger('withStalkerRecent');
24→    return signalStoreFeature(
25→        withMethods(
26→            (
27→                store,
28→                playlistService = inject(PlaylistsService),
29→                ngrxStore = inject(Store)
30→            ) => {
31→                const storeContext = store as unknown as RecentStoreContext;
32→
33→                return {
34→                    addToRecentlyViewed(item: RecentlyViewedPayload) {
35→                        const portalId = storeContext.currentPlaylist()?._id;
36→                        const recentItem = {
37→                            ...item,
38→                            category_id: storeContext.selectedContentType(),
39→                            added_at: Date.now(),
40→                            id: item.id ?? item.stream_id ?? '',
41→                            title:
42→                                item.title ??
43→                                item.name ??
44→                                item.o_name ??
45→                                '',
46→                        };
47→                        playlistService
48→                            .addPortalRecentlyViewed(portalId, recentItem)
49→                            .subscribe((updatedPlaylist) => {
50→                                ngrxStore.dispatch(
51→                                    PlaylistActions.updatePlaylistMeta({
52→                                        playlist: {
53→                                            _id: portalId,
54→                                            recentlyViewed:
55→                                                updatedPlaylist?.recentlyViewed,
56→                                        } as PlaylistMeta,
57→                                    })
58→                                );
59→                            });
60→                    },
61→                    removeFromRecentlyViewed(
62→                        itemId: string | number,
63→                        onComplete?: () => void
64→                    ) {
65→                        const portalId = storeContext.currentPlaylist()?._id;
66→                        playlistService
67→                            .removeFromPortalRecentlyViewed(portalId, itemId)
68→                            .subscribe({
69→                                next: (updatedPlaylist) => {
70→                                    ngrxStore.dispatch(
71→                                        PlaylistActions.updatePlaylistMeta({
72→                                            playlist: {
73→                                                _id: portalId,
74→                                                recentlyViewed:
75→                                                    updatedPlaylist?.recentlyViewed,
76→                                            } as PlaylistMeta,
77→                                        })
78→                                    );
79→                                    onComplete?.();
80→                                },
81→                                error: (error) =>
82→                                    logger.error(
83→                                        'Failed to remove item from recently viewed',
84→                                        error
85→                                    ),
86→                            });
87→                    },
88→                };
89→            }
90→        )
91→    );
92→}
