417→    }
418→
419→    async selectLiveItem(item: StalkerVodSource) {
420→        this.selectedLiveItem.set(item);
421→        this.liveStreamUrl.set('');
422→        this.stalkerStore.setSelectedContentType('itv');
423→        this.stalkerStore.setSelectedItem(item);
424→        this.isResolvingPlayback.set(true);
425→
426→        try {
427→            const playback = await this.stalkerStore.resolveItvPlayback(item);
428→            await this.loadEpgForChannel(item.id);
429→            this.liveStreamUrl.set(playback.streamUrl);
430→
431→            if (!this.isEmbeddedPlayer()) {
432→                void this.portalPlayer.openResolvedPlayback(playback, true);
433→            }
434→        } catch (error) {
435→            this.logger.error('Failed to resolve ITV playback', error);
436→            this.showPlaybackError(error);
437→        } finally {
438→            this.isResolvingPlayback.set(false);
439→        }
440→    }
441→
442→    async loadMoreEpg() {
443→        if (!this.epgChannelId || this.isLoadingEpg()) {
444→            return;
445→        }
446→
447→        this.epgPageSize += 10;
448→        this.isLoadingEpg.set(true);
449→        try {
450→            const items = await this.stalkerStore.fetchChannelEpg(
451→                this.epgChannelId,
452→                this.epgPageSize
453→            );
454→            this.epgItems.set(items);
455→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
456→        } catch {
457→            this.hasMoreEpg.set(false);
458→        } finally {
459→            this.isLoadingEpg.set(false);
460→        }
461→    }
462→
463→    async createLinkToPlayVodItv(
464→        cmd?: string,
465→        title?: string,
466→        thumbnail?: string
467→    ) {
468→        this.logger.debug('Create link to play VOD/ITV', {
469→            cmd,
470→            title,
471→            thumbnail,
472→        });
473→        await this.stalkerStore.createLinkToPlayVod(cmd, title, thumbnail);
