482→    }
483→
484→    toggleLiveFavorite(item: StalkerVodSource): void {
485→        const itemId = String(item.id ?? '');
486→        if (this.liveFavoriteIds().has(itemId)) {
487→            this.removeFromFavorites(itemId);
488→            return;
489→        }
490→
491→        this.addToFavorites({
492→            ...item,
493→            category_id: 'itv',
494→            title: item.o_name || item.name,
495→            cover: item.logo || item.cover,
