510→    private clearLiveSelection() {
511→        this.selectedLiveItem.set(null);
512→        this.liveStreamUrl.set('');
513→        this.isResolvingPlayback.set(false);
514→        this.epgItems.set([]);
515→        this.isLoadingEpg.set(false);
516→        this.hasMoreEpg.set(false);
517→        this.epgChannelId = null;
518→        this.stalkerStore.setSelectedItem(null);
519→    }
