521→    /**
522→     * Normalize recent item to ensure is_series flag is properly set
523→     * and all required fields are present for the series view
524→     */
525→    private normalizeRecentItem(
526→        item: StalkerVodSource
527→    ): StalkerSelectedVodItem {
528→        return normalizeStalkerVodDetailsItem(item);
529→    }
