531→    private syncSelectedVodFavorite(): void {
532→        this.isSelectedVodFavorite.set(
533→            isSelectedStalkerVodFavorite(
534→                this.vodDetailsItem,
535→                this.portalFavorites.value() ?? []
536→            )
537→        );
538→    }
