540→    private clearDetailsView(): void {
541→        const cleared = clearStalkerDetailViewState();
542→        this.itemDetails = cleared.itemDetails;
543→        this.vodDetailsItem = cleared.vodDetailsItem;
544→        this.isSelectedVodFavorite.set(false);
