558→    private async loadEpgForChannel(channelId: number | string | undefined) {
559→        if (channelId === undefined || channelId === null) {
560→            this.epgItems.set([]);
561→            this.hasMoreEpg.set(false);
562→            return;
563→        }
564→
565→        this.epgChannelId = channelId;
566→        this.epgPageSize = 10;
567→        this.isLoadingEpg.set(true);
568→        this.epgItems.set([]);
569→        this.hasMoreEpg.set(false);
570→
571→        try {
572→            const items = await this.stalkerStore.fetchChannelEpg(
573→                channelId,
574→                this.epgPageSize
575→            );
576→            this.epgItems.set(items);
577→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
578→        } catch {
579→            this.epgItems.set([]);
580→        } finally {
581→            this.isLoadingEpg.set(false);
582→        }
583→    }
584→
585→    private showPlaybackError(error: unknown): void {
586→        const errorMessage =
587→            error instanceof Error && error.message === 'nothing_to_play'
588→                ? this.translate.instant('PORTALS.CONTENT_NOT_AVAILABLE')
589→                : this.translate.instant('PORTALS.PLAYBACK_ERROR');
590→        this.snackBar.open(errorMessage, undefined, { duration: 3000 });
591→    }
592→}
