122→                            )
123→                                this.dataService.sendIpcEvent(OPEN_VLC_PLAYER, {
124→                                    url:
125→                                        activeChannel?.url +
126→                                        (activeChannel?.epgParams ?? ''),
127→                                    title: activeChannel?.name ?? '',
128→                                    'user-agent':
129→                                        activeChannel?.http?.['user-agent'],
130→                                    referer: activeChannel?.http?.referrer,
131→                                    origin: activeChannel?.http?.origin,
132→                                });
133→                        }
134→                    );
135→                })
136→            );
137→        },
138→        { dispatch: false }
139→    );
140→
141→    setActiveChannel$ = createEffect(() => {
142→        return this.actions$.pipe(
143→            ofType(ChannelActions.setActiveChannel),
144→            // Skip the effect entirely when channel is falsy
145→            filter((action) => !!action.channel),
146→            map((action) => {
147→                const { channel } = action;
148→
149→                // Use modern EPG service to get channel programs
150→                const channelId = channel.tvg?.id || channel.name;
151→                if (channelId) {
152→                    this.epgService.getChannelPrograms(channelId);
153→                }
154→
155→                // Set user agent if specified on channel
156→                if (channel.http['user-agent']) {
157→                    window.electron?.setUserAgent(
158→                        channel.http['user-agent'],
159→                        channel.http.referrer
160→                    );
161→                }
162→
163→                firstValueFrom(this.storage.get(STORE_KEY.Settings)).then(
164→                    (settings: any) => {
165→                        if (
166→                            settings &&
167→                            Object.keys(settings).length > 0 &&
168→                            settings.player === VideoPlayer.MPV &&
169→                            channel.radio !== 'true'
170→                        ) {
171→                            this.dataService.sendIpcEvent(OPEN_MPV_PLAYER, {
172→                                url: channel.url,
173→                                title: channel.name ?? '',
174→                                'user-agent': channel.http['user-agent'],
175→                                referer: channel.http.referrer,
176→                                origin: channel.http.origin,
177→                            });
178→                        } else if (
179→                            settings &&
180→                            Object.keys(settings).length > 0 &&
181→                            settings.player === VideoPlayer.VLC &&
182→                            channel.radio !== 'true'
183→                        )
184→                            this.dataService.sendIpcEvent(OPEN_VLC_PLAYER, {
185→                                url: channel.url,
186→                                title: channel.name ?? '',
187→                                'user-agent': channel.http['user-agent'],
188→                                referer: channel.http.referrer,
189→                                origin: channel.http.origin,
190→                            });
191→                    }
192→                );
193→
194→                return ChannelActions.setActiveChannelSuccess({
195→                    channel: action.channel,
196→                });
197→            })
198→        );
199→    });
