 99→    private router = inject(Router);
100→    private store = inject(Store);
101→    private xtreamStore = inject(XtreamStore);
102→    private portalPlayer = inject(PORTAL_PLAYER);
103→    private readonly favoritesCtx = inject(FavoritesContextService);
104→
105→    readonly currentPlaylist = this.xtreamStore.currentPlaylist;
