107→    readonly playlistSubtitle = 'Xtream Code';
108→    readonly playlistTitle = computed(
109→        () =>
110→            this.currentPlaylist()?.name ||
111→            this.currentPlaylist()?.title ||
112→            'Playlist'
113→    );
114→
115→    readonly allItems = signal<FavoriteItem[]>([]);
116→    readonly series = signal<FavoriteItem[]>([]);
117→    readonly movies = signal<FavoriteItem[]>([]);
118→    readonly live = signal<FavoriteItem[]>([]);
119→    readonly searchTerm = queryParamSignal(this.route, 'q', (value) =>
120→        (value ?? '').trim().toLowerCase()
121→    );
122→    readonly categories = computed(() =>
123→        buildStandardCollectionCategories({
124→            labels: XTREAM_COLLECTION_LABELS,
125→            counts: {
126→                all: this.allItems().length,
127→                movie: this.movies().length,
128→                live: this.live().length,
129→                series: this.series().length,
130→            },
131→            includeLive: true,
132→        })
133→    );
134→    readonly collectionContext = createPortalCollectionContext({
135→        ctx: this.favoritesCtx,
136→        categories: this.categories,
137→    });
138→    readonly selectedLiveItem = signal<XtreamFavoriteLiveItem | null>(null);
139→    readonly liveStreamUrl = signal('');
140→    readonly mode = computed<PortalCollectionMode>(() =>
141→        this.isLiveCategory() ? 'live' : 'grid'
142→    );
143→    readonly liveItemsToShow = computed(() =>
144→        this.live().filter((item) => {
145→            const term = this.searchTerm();
146→            if (!term) {
147→                return true;
148→            }
149→
150→            return `${item?.title ?? ''}`.toLowerCase().includes(term);
151→        })
152→    );
153→    readonly isLiveCategory = computed(
154→        () => this.selectedCategoryId() === 'live'
155→    );
156→    readonly isEmbeddedPlayer = computed(() =>
157→        this.portalPlayer.isEmbeddedPlayer()
158→    );
159→    readonly liveChannelSortMode = signal<LiveChannelSortMode>('server');
160→    readonly liveChannelSortLabel = computed(() => {
161→        const mode = this.liveChannelSortMode();
162→        if (mode === 'name-asc') return 'Name A-Z';
163→        if (mode === 'name-desc') return 'Name Z-A';
164→        return 'Server Order';
165→    });
166→    readonly epgItems = this.xtreamStore.epgItems;
167→    readonly isLoadingEpg = this.xtreamStore.isLoadingEpg;
168→
169→    /** Synced with the workspace context service so panel clicks are reactive */
170→    readonly selectedCategoryId = this.collectionContext.selectedCategoryId;
171→
172→    /** Items filtered by the active category — fully reactive, no imperative calls */
173→    readonly filteredFavoritesToShow = computed(() => {
174→        return filterCollectionBucket({
175→            selectedCategoryId: this.selectedCategoryId(),
176→            allItems: this.allItems(),
177→            buckets: {
178→                movie: this.movies(),
179→                live: this.live(),
180→                series: this.series(),
181→            },
182→            searchTerm: this.searchTerm(),
183→            textOf: (item) => `${item?.title ?? ''}`,
184→        });
185→    });
186→
187→    private favoritesRefresh$ = new BehaviorSubject<void>(undefined);
188→
189→    constructor() {
190→        effect(() => {
191→            const selectedItem = this.selectedLiveItem();
192→            if (!selectedItem) {
193→                return;
194→            }
195→
196→            const stillExists = this.liveItemsToShow().some(
197→                (item) =>
198→                    Number(item.xtream_id) === Number(selectedItem.xtream_id)
199→            );
200→
201→            if (!stillExists) {
202→                this.clearLiveSelection();
203→            }
204→        });
205→
206→        effect(() => {
207→            if (this.isLiveCategory()) {
208→                return;
209→            }
210→
211→            this.clearLiveSelection();
212→        });
213→    }
214→
215→    ngOnInit() {
216→        this.xtreamStore.setSelectedContentType(undefined);
217→        const savedSortMode = localStorage.getItem(
218→            XTREAM_FAVORITES_LIVE_SORT_STORAGE_KEY
219→        );
220→        if (
221→            savedSortMode === 'server' ||
222→            savedSortMode === 'name-asc' ||
223→            savedSortMode === 'name-desc'
224→        ) {
225→            this.liveChannelSortMode.set(savedSortMode);
226→        }
227→        const playlistId = this.store.selectSignal(selectActivePlaylist)()._id;
228→        this.favoritesRefresh$
229→            .pipe(
230→                switchMap(() => this.favoritesService.getFavorites(playlistId))
231→            )
232→            .subscribe((items) => {
233→                this.allItems.set(items);
234→                this.movies.set(
235→                    items.filter(
236→                        (item) => item.type === 'movie' || item.type === 'vod'
237→                    )
238→                );
239→                this.live.set(items.filter((item) => item.type === 'live'));
240→                this.series.set(items.filter((item) => item.type === 'series'));
241→            });
242→    }
243→
244→    setCategoryId(categoryId: string) {
245→        this.collectionContext.setCategoryId(categoryId);
246→    }
247→
248→    async removeFromFavorites(item: FavoriteLayoutItem) {
249→        if (!isXtreamFavoriteRouteItem(item)) {
250→            return;
251→        }
252→
253→        await this.favoritesService.removeFromFavorites(
254→            item.content_id,
255→            item.playlist_id
256→        );
257→        this.favoritesRefresh$.next();
258→    }
259→
260→    openItem(item: FavoriteLayoutItem) {
261→        if (!isXtreamFavoriteRouteItem(item)) {
262→            return;
263→        }
264→
265→        const type = item.type === 'movie' ? 'vod' : item.type;
266→        this.xtreamStore.setSelectedContentType(type);
267→        if (type === 'live') {
268→            this.setCategoryId('live');
269→            this.selectLiveItem(item);
270→        } else {
271→            const routePlaylistId = this.route.snapshot.params['id'];
272→            const hasGlobalContext = this.router.url.includes(
273→                '/workspace/global-favorites'
274→            );
275→            const shouldNavigateAbsolute =
276→                hasGlobalContext ||
277→                (item.playlist_id &&
278→                    routePlaylistId &&
279→                    item.playlist_id !== routePlaylistId);
280→
281→            if (shouldNavigateAbsolute && item.playlist_id) {
282→                this.router.navigate([
283→                    '/workspace',
284→                    'xtreams',
285→                    item.playlist_id,
286→                    type,
287→                    item.category_id,
288→                    item.xtream_id,
289→                ]);
290→                return;
291→            }
292→
293→            this.router.navigate(
294→                ['..', type, item.category_id, item.xtream_id],
295→                {
296→                    relativeTo: this.route,
297→                }
298→            );
299→        }
300→    }
301→
302→    selectLiveItem(item: XtreamFavoriteLiveItem) {
303→        this.xtreamStore.setSelectedContentType('live');
304→        this.selectedLiveItem.set(item);
305→        const streamUrl = this.xtreamStore.constructStreamUrl(item);
306→        this.liveStreamUrl.set(streamUrl);
307→
308→        if (this.isEmbeddedPlayer()) {
309→            return;
310→        }
311→
312→        this.xtreamStore.openPlayer(
313→            streamUrl,
314→            item.title ?? '',
315→            item.poster_url || item.stream_icon || null
316→        );
317→    }
318→
319→    setLiveChannelSortMode(mode: LiveChannelSortMode): void {
320→        this.liveChannelSortMode.set(mode);
321→        localStorage.setItem(XTREAM_FAVORITES_LIVE_SORT_STORAGE_KEY, mode);
322→    }
323→
324→    private clearLiveSelection() {
325→        this.selectedLiveItem.set(null);
326→        this.liveStreamUrl.set('');
327→        this.xtreamStore.clearEpg();
328→        this.xtreamStore.setSelectedItem(null);
329→    }
330→}
