334→        effect(() => {
335→            if (this.isGlobal) {
336→                return;
337→            }
338→
339→            const selectedItem = this.selectedLiveItem();
340→            if (!selectedItem) {
341→                return;
342→            }
343→
344→            const stillExists = this.liveItemsToShow().some(
345→                (item) =>
346→                    Number(item.xtream_id ?? item.id) ===
347→                    Number(selectedItem.xtream_id ?? selectedItem.id)
348→            );
349→
350→            if (!stillExists) {
351→                this.clearLiveSelection();
