402→                            name: item.title,
403→                            category_id:
404→                                item.type === 'movie'
405→                                    ? 'vod'
406→                                    : item.type === 'live'
407→                                      ? 'itv'
408→                                      : 'series',
409→                            cover: item.poster_url,
410→                        },
411→                    },
412→                }
