542→
543→    setCategoryId(categoryId: string): void {
544→        this.collectionContext.setCategoryId(categoryId);
545→    }
546→
547→    selectLiveItem(item: XtreamRecentLiveItem): void {
548→        this.xtreamStore.setSelectedContentType('live');
549→        this.selectedLiveItem.set(item);
550→        const streamUrl = this.xtreamStore.constructStreamUrl(item);
