569→    private clearLiveSelection(): void {
570→        this.selectedLiveItem.set(null);
571→        this.liveStreamUrl.set('');
572→        this.xtreamStore.clearEpg();
573→        this.xtreamStore.setSelectedItem(null);
574→    }
575→}
