509→    private async loadEpgForChannel(channelId: number | string | undefined) {
510→        if (channelId === undefined || channelId === null) {
511→            this.epgItems.set([]);
512→            this.hasMoreEpg.set(false);
513→            return;
514→        }
515→
516→        this.epgChannelId = channelId;
517→        this.epgPageSize = 10;
518→        this.isLoadingEpg.set(true);
519→        this.epgItems.set([]);
520→        this.hasMoreEpg.set(false);
521→
522→        try {
523→            const items = await this.stalkerStore.fetchChannelEpg(
524→                channelId,
525→                this.epgPageSize
526→            );
527→            this.epgItems.set(items);
528→            this.hasMoreEpg.set(items.length >= this.epgPageSize);
529→        } catch {
530→            this.epgItems.set([]);
531→        } finally {
532→            this.isLoadingEpg.set(false);
533→        }
534→    }
