536→    private showPlaybackError(error: unknown): void {
537→        const errorMessage =
538→            error instanceof Error && error.message === 'nothing_to_play'
539→                ? this.translate.instant('PORTALS.CONTENT_NOT_AVAILABLE')
540→                : this.translate.instant('PORTALS.PLAYBACK_ERROR');
541→        this.snackBar.open(errorMessage, undefined, { duration: 3000 });
542→    }
