243→            const previousCategoryId = this.previousSelectedCategoryId;
244→
245→            this.previousSelectedCategoryId = selectedCategoryId;
246→
247→            if (
248→                hasInlineDetail &&
249→                previousCategoryId !== null &&
250→                previousCategoryId !== selectedCategoryId
251→            ) {
252→                this.clearDetailsView();
253→            }
254→        });
255→
256→        effect(() => {
257→            const refresh = this.refreshToken();
258→            if (!refresh) {
259→                return;
260→            }
261→
262→            this.collectionRefresh.refresh();
263→        });
264→
265→        effect(() => {
266→            const playlist = this.currentPlaylist();
267→            if (!playlist?._id) return;
268→
269→            const state =
270→                this.router.currentNavigation()?.extras?.state ??
271→                window.history.state;
272→            const item = state?.openRecentItem;
273→            if (
274→                !item ||
275→                !RecentlyViewedComponent.isCategoryType(item.category_id)
276→            ) {
277→                return;
278→            }
279→
280→            this.openItem(item);
281→
282→            // Clear consumed history state to avoid reopening item on reload/back.
283→            try {
284→                window.history.replaceState({}, document.title);
285→            } catch {
286→                // no-op
287→            }
288→        });
289→
290→        effect(() => {
291→            const selectedItem = this.selectedLiveItem();
292→            if (!selectedItem) {
293→                return;
294→            }
295→
296→            const stillExists = this.liveItemsToShow().some(
297→                (item) => String(item.id ?? '') === String(selectedItem.id ?? '')
298→            );
299→
300→            if (!stillExists) {
301→                this.clearLiveSelection();
302→            }
303→        });
304→
305→        effect(() => {
