587→            error instanceof Error && error.message === 'nothing_to_play'
588→                ? this.translate.instant('PORTALS.CONTENT_NOT_AVAILABLE')
589→                : this.translate.instant('PORTALS.PLAYBACK_ERROR');
590→        this.snackBar.open(errorMessage, undefined, { duration: 3000 });
591→    }
