183→    private async loadFavorites(): Promise<void> {
184→        this.isLoading.set(true);
185→        try {
186→            const channels =
187→                await this.favoritesService.getUnifiedLiveFavorites();
188→            this.channels.set(channels);
189→            // Load EPG in background without blocking
190→            this.loadEpgForChannels(channels);
191→        } catch {
192→            this.channels.set([]);
193→        } finally {
194→            this.isLoading.set(false);
195→        }
196→    }
197→
198→    private async loadEpgForChannels(
199→        channels: UnifiedFavoriteChannel[]
200→    ): Promise<void> {
201→        const epgMap = new Map<string, EpgProgram | null>(this.epgMap());
202→        const now = Date.now();
203→
204→        // Group xtream channels by playlistId to batch credential lookups
205→        const xtreamByPlaylist = new Map<string, UnifiedFavoriteChannel[]>();
206→        for (const ch of channels) {
207→            if (ch.sourceType === 'xtream') {
208→                const list = xtreamByPlaylist.get(ch.playlistId) ?? [];
209→                list.push(ch);
210→                xtreamByPlaylist.set(ch.playlistId, list);
211→            }
212→        }
213→
214→        const tasks: Promise<void>[] = [];
215→
216→        // M3U EPG
217→        for (const ch of channels) {
218→            if (ch.sourceType !== 'm3u' || !ch.tvgId) continue;
219→            tasks.push(this.loadM3uEpg(ch, epgMap, now));
220→        }
221→
222→        // Xtream EPG – one credential lookup per playlist
223→        for (const [playlistId, chList] of xtreamByPlaylist.entries()) {
224→            tasks.push(
225→                this.loadXtreamEpgForPlaylist(playlistId, chList, epgMap, now)
226→            );
227→        }
228→
229→        await Promise.all(tasks.map((t) => t.catch(() => null)));
230→        this.epgMap.set(new Map(epgMap));
231→    }
232→
233→    private async loadM3uEpg(
234→        ch: UnifiedFavoriteChannel,
235→        epgMap: Map<string, EpgProgram | null>,
236→        now: number
237→    ): Promise<void> {
238→        if (!window.electron?.getChannelPrograms || !ch.tvgId) return;
239→        try {
240→            const programs: EpgProgram[] =
241→                await window.electron.getChannelPrograms(ch.tvgId);
242→            const current =
243→                programs.find(
244→                    (p) =>
245→                        new Date(p.start).getTime() <= now &&
246→                        now < new Date(p.stop).getTime()
247→                ) ?? null;
248→            epgMap.set(ch.tvgId.trim(), current);
249→        } catch {
250→            epgMap.set(ch.tvgId.trim(), null);
251→        }
252→    }
253→
254→    private async loadXtreamEpgForPlaylist(
255→        playlistId: string,
256→        channels: UnifiedFavoriteChannel[],
257→        epgMap: Map<string, EpgProgram | null>,
258→        now: number
259→    ): Promise<void> {
260→        let playlist: Playlist | undefined;
261→        try {
262→            playlist = await firstValueFrom(
263→                this.playlistsService.getPlaylistById(playlistId)
264→            );
265→        } catch {
266→            return;
267→        }
268→
269→        if (!playlist?.serverUrl || !playlist.username || !playlist.password) {
270→            return;
271→        }
272→
273→        const credentials = {
274→            serverUrl: playlist.serverUrl,
275→            username: playlist.username,
276→            password: playlist.password,
277→        };
278→
279→        await Promise.all(
280→            channels
281→                .map(async (ch) => {
282→                    if (!ch.xtreamId) return;
283→                    try {
284→                        const items: EpgItem[] =
285→                            await this.xtreamApi.getShortEpg(
286→                                credentials,
287→                                ch.xtreamId,
288→                                2
289→                            );
290→                        const nowSec = Math.floor(now / 1000);
291→                        const current =
292→                            items.find(
293→                                (p) =>
294→                                    Number(p.start_timestamp) <= nowSec &&
295→                                    nowSec < Number(p.stop_timestamp)
296→                            ) ?? null;
297→
298→                        const epgKey = ch.tvgId?.trim() || ch.name?.trim();
299→                        if (epgKey) {
300→                            epgMap.set(
301→                                epgKey,
302→                                current
303→                                    ? {
304→                                          start: new Date(
305→                                              Number(current.start_timestamp) *
306→                                                  1000
307→                                          ).toISOString(),
308→                                          stop: new Date(
309→                                              Number(current.stop_timestamp) *
310→                                                  1000
311→                                          ).toISOString(),
312→                                          channel: String(ch.xtreamId),
313→                                          title: current.title,
314→                                          desc: current.description ?? null,
315→                                          category: null,
316→                                      }
317→                                    : null
318→                            );
319→                        }
320→                    } catch {
321→                        // skip
322→                    }
323→                })
324→                .map((t) => t.catch(() => null))
325→        );
326→    }
327→
328→    private async resolvePlayback(
329→        ch: UnifiedFavoriteChannel
330→    ): Promise<ResolvedPortalPlayback> {
331→        switch (ch.sourceType) {
332→            case 'm3u':
333→                return this.resolveM3uPlayback(ch);
334→            case 'xtream':
335→                return this.resolveXtreamPlayback(ch);
336→            case 'stalker':
337→                return this.resolveStalkerPlayback(ch);
338→        }
339→    }
340→
341→    private async loadEpgItemsForChannel(
342→        ch: UnifiedFavoriteChannel
343→    ): Promise<EpgItem[]> {
344→        try {
345→            if (
346→                ch.sourceType === 'm3u' &&
347→                ch.tvgId &&
348→                window.electron?.getChannelPrograms
349→            ) {
350→                const programs: EpgProgram[] =
351→                    await window.electron.getChannelPrograms(ch.tvgId);
352→                return programs.map((p, i) => ({
353→                    id: String(i),
354→                    epg_id: p.channel,
355→                    title: p.title,
356→                    lang: 'en',
357→                    start: p.start,
358→                    end: p.stop,
359→                    stop: p.stop,
360→                    description: p.desc ?? '',
361→                    channel_id: p.channel,
362→                    start_timestamp: String(
363→                        Math.floor(new Date(p.start).getTime() / 1000)
364→                    ),
365→                    stop_timestamp: String(
366→                        Math.floor(new Date(p.stop).getTime() / 1000)
367→                    ),
368→                }));
369→            }
370→            if (ch.sourceType === 'xtream' && ch.xtreamId) {
371→                const playlist = (await firstValueFrom(
372→                    this.playlistsService.getPlaylistById(ch.playlistId)
373→                )) as Playlist | undefined;
374→                if (
375→                    !playlist?.serverUrl ||
376→                    !playlist.username ||
377→                    !playlist.password
378→                ) {
379→                    return [];
380→                }
381→                return await this.xtreamApi.getShortEpg(
382→                    {
383→                        serverUrl: playlist.serverUrl,
384→                        username: playlist.username,
385→                        password: playlist.password,
386→                    },
387→                    ch.xtreamId,
388→                    10
389→                );
390→            }
391→        } catch {
392→            // ignore
393→        }
394→        return [];
395→    }
396→
397→    private resolveM3uPlayback(
398→        ch: UnifiedFavoriteChannel
399→    ): ResolvedPortalPlayback {
400→        return {
401→            streamUrl: ch.streamUrl ?? '',
402→            title: ch.name,
403→            thumbnail: ch.logo ?? null,
404→        };
405→    }
406→
407→    private async resolveXtreamPlayback(
408→        ch: UnifiedFavoriteChannel
409→    ): Promise<ResolvedPortalPlayback> {
410→        const playlist = (await firstValueFrom(
411→            this.playlistsService.getPlaylistById(ch.playlistId)
412→        )) as Playlist | undefined;
413→        if (
414→            ch.xtreamId == null ||
415→            !playlist?.serverUrl ||
416→            !playlist.username ||
417→            !playlist.password
418→        ) {
419→            throw new Error('Missing Xtream playback credentials');
420→        }
421→        const credentials = {
422→            serverUrl: playlist.serverUrl,
423→            username: playlist.username,
424→            password: playlist.password,
425→        };
426→        const streamUrl = this.xtreamUrl.constructLiveUrl(credentials, ch.xtreamId);
427→        return {
428→            streamUrl,
429→            title: ch.name,
430→            thumbnail: ch.logo ?? null,
431→        };
432→    }
433→
434→    private async resolveStalkerPlayback(
435→        ch: UnifiedFavoriteChannel
436→    ): Promise<ResolvedPortalPlayback> {
437→        const playlist = (await firstValueFrom(
438→            this.playlistsService.getPlaylistById(ch.playlistId)
439→        )) as Playlist | undefined;
440→
441→        const portalUrl =
442→            ch.stalkerPortalUrl ?? playlist?.portalUrl ?? playlist?.url ?? '';
443→        const macAddress = ch.stalkerMacAddress ?? playlist?.macAddress ?? '';
444→        const cmd = ch.stalkerCmd ?? '';
445→
446→        const params = {
447→            action: StalkerPortalActions.CreateLink,
448→            cmd,
449→            type: 'itv' as const,
450→            disable_ad: '0',
451→            download: '0',
452→            JsHttpRequest: '1-xml',
453→        };
454→
455→        let response: StalkerCreateLinkResponse | undefined;
456→        if (playlist?.isFullStalkerPortal && playlist) {
457→            response = await this.stalkerSession.makeAuthenticatedRequest(
458→                playlist,
459→                params
460→            );
461→        } else {
462→            response = await this.dataService.sendIpcEvent(STALKER_REQUEST, {
463→                url: portalUrl,
464→                macAddress,
465→                params,
466→            });
467→        }
468→
469→        const rawCmd = response?.js?.cmd ?? '';
470→        const streamUrl = this.normalizeStalkerCmd(rawCmd);
471→
472→        return {
473→            streamUrl,
474→            title: ch.name,
475→            thumbnail: ch.logo ?? null,
476→        };
477→    }
478→
479→    private normalizeStalkerCmd(value: string): string {
480→        const trimmed = String(value ?? '').trim();
481→        if (!trimmed) return '';
482→        const splitAt = trimmed.indexOf(' ');
483→        if (splitAt > 0) {
484→            const candidate = trimmed.slice(splitAt + 1).trim();
485→            if (
486→                candidate.startsWith('http://') ||
487→                candidate.startsWith('https://')
488→            ) {
489→                return candidate;
490→            }
491→        }
492→        return trimmed;
493→    }
494→}
