 27→@Component({
 28→    selector: 'app-global-favorites-list',
 29→    templateUrl: './global-favorites-list.component.html',
 30→    styleUrl: './global-favorites-list.component.scss',
 31→    changeDetection: ChangeDetectionStrategy.OnPush,
 32→    imports: [
 33→        ChannelListItemComponent,
 34→        DragDropModule,
 35→        MatFormFieldModule,
 36→        MatIconModule,
 37→        MatInputModule,
 38→        TranslatePipe,
 39→    ],
 40→})
 41→export class GlobalFavoritesListComponent {
 42→    readonly channels = input.required<UnifiedFavoriteChannel[]>();
 43→    readonly epgMap = input<Map<string, EpgProgram | null>>(new Map());
 44→    readonly progressTick = input<number>(0);
 45→    readonly activeUid = input<string | null>(null);
 46→
 47→    readonly channelSelected = output<UnifiedFavoriteChannel>();
 48→    readonly channelsReordered = output<UnifiedFavoriteChannel[]>();
 49→    readonly favoriteToggled = output<UnifiedFavoriteChannel>();
 50→
 51→    readonly searchTerm = signal('');
 52→
 53→    readonly enrichedChannels = computed((): EnrichedUnifiedFavorite[] => {
 54→        const channels = this.channels();
 55→        const epgMap = this.epgMap();
 56→        const term = this.searchTerm().toLowerCase();
 57→        // Read progressTick to trigger periodic recalculation
 58→        this.progressTick();
 59→
 60→        const filtered = term
 61→            ? channels.filter((ch) => ch.name.toLowerCase().includes(term))
 62→            : channels;
 63→
 64→        return filtered.map((ch) => {
 65→            const epgKey = ch.tvgId?.trim() || ch.name?.trim();
 66→            const currentEpgProgram = epgKey
 67→                ? (epgMap.get(epgKey) ?? null)
 68→                : null;
 69→            return {
 70→                ...ch,
 71→                currentEpgProgram,
 72→                progressPercentage: this.calcProgress(currentEpgProgram),
 73→            };
 74→        });
 75→    });
 76→
 77→    onChannelClick(channel: UnifiedFavoriteChannel): void {
 78→        this.channelSelected.emit(channel);
 79→    }
 80→
 81→    onFavoriteToggled(channel: UnifiedFavoriteChannel): void {
 82→        this.favoriteToggled.emit(channel);
 83→    }
 84→
 85→    onDrop(event: CdkDragDrop<EnrichedUnifiedFavorite[]>): void {
 86→        // Disable reorder while searching to avoid index confusion
 87→        if (this.searchTerm()) return;
 88→        const list = [...this.channels()];
 89→        moveItemInArray(list, event.previousIndex, event.currentIndex);
 90→        this.channelsReordered.emit(list);
 91→    }
 92→
 93→    trackByUid(_: number, ch: EnrichedUnifiedFavorite): string {
 94→        return ch.uid;
 95→    }
 96→
 97→    private calcProgress(program: EpgProgram | null | undefined): number {
 98→        if (!program) return 0;
 99→        const now = Date.now();
100→        const start = new Date(program.start).getTime();
101→        const stop = new Date(program.stop).getTime();
102→        const total = stop - start;
103→        const elapsed = now - start;
104→        return Math.min(100, Math.max(0, (elapsed / total) * 100));
105→    }
106→}
