  6→    withState,
  7→} from '@ngrx/signals';
  8→import { rxMethod } from '@ngrx/signals/rxjs-interop';
  9→import { firstValueFrom, pipe, switchMap, tap } from 'rxjs';
 10→import { DatabaseService, PlaylistsService } from 'services';
 11→import {
 12→    buildPlaylistRecentItems,
 13→    Playlist,
 14→    PortalRecentItem,
 15→} from 'shared-interfaces';
 16→import { createLogger } from '@iptvnator/portal/shared/util';
 17→
 18→export interface RecentlyViewedItem extends PortalRecentItem {
 19→    /** @deprecated Redundant — always equals `id`. Retained for compat. */
 20→    content_id: number | string;
 21→}
 22→
 23→function mapDbRecentItem(
 24→    item: {
 25→        id: number;
 26→        title: string;
 27→        type: string;
 28→        poster_url: string;
 29→        viewed_at?: string;
 30→        xtream_id: number;
 31→        category_id: number;
 32→    },
 33→    playlistId: string
 34→): RecentlyViewedItem {
 35→    return {
 36→        id: item.id,
 37→        title: item.title,
 38→        type: item.type as 'live' | 'movie' | 'series',
 39→        poster_url: item.poster_url,
 40→        content_id: item.id,
 41→        playlist_id: playlistId,
 42→        viewed_at: item.viewed_at || '',
 43→        xtream_id: item.xtream_id,
 44→        category_id: item.category_id,
 45→    };
 46→}
 47→
 48→export const withRecentItems = function () {
 49→    const logger = createLogger('withRecentItems');
 50→    return signalStoreFeature(
 51→        withState({
 52→            recentItems: [],
 53→        }),
 54→        withMethods((store, dbService = inject(DatabaseService)) => ({
 55→            loadRecentItems: rxMethod<{ id: string }>(
 56→                pipe(
 57→                    switchMap(async (playlist) => {
 58→                        const items = await dbService.getRecentItems(
 59→                            playlist.id
 60→                        );
 61→                        return items.map((item) =>
 62→                            mapDbRecentItem(item, playlist.id)
 63→                        );
 64→                    }),
 65→                    tap((items: RecentlyViewedItem[]) =>
 66→                        patchState(store, { recentItems: items })
 67→                    )
 68→                )
 69→            ),
 70→        })),
 71→        withMethods(
 72→            (
 73→                store,
 74→                dbService = inject(DatabaseService),
 75→                playlistsService = inject(PlaylistsService)
 76→            ) => ({
 77→                addRecentItem: rxMethod<{
 78→                    contentId: number;
 79→                    playlist: Signal<{ id: string }>;
 80→                }>(
 81→                    pipe(
 82→                        switchMap(async ({ contentId, playlist }) => {
 83→                            // contentId is actually xtream_id, need to look up the database content.id
 84→                            const playlistId = playlist().id;
 85→                            const content =
 86→                                await dbService.getContentByXtreamId(
 87→                                    contentId,
 88→                                    playlistId
 89→                                );
 90→                            if (content) {
 91→                                await dbService.addRecentItem(
 92→                                    content.id,
 93→                                    playlistId
 94→                                );
 95→
 96→                                // Reload after add/update so re-watched items
 97→                                // immediately move to the top in recently-viewed.
 98→                                const items =
 99→                                    await dbService.getRecentItems(playlistId);
100→                                patchState(store, {
101→                                    recentItems: items.map((item) =>
102→                                        mapDbRecentItem(item, playlistId)
103→                                    ),
104→                                });
105→                            }
106→                        })
107→                    )
108→                ),
109→                clearRecentItems: rxMethod<{ id: string }>(
110→                    pipe(
111→                        switchMap(async (playlist) => {
112→                            await dbService.clearPlaylistRecentItems(
113→                                playlist.id
114→                            );
115→                            patchState(store, { recentItems: [] });
116→                        })
117→                    )
118→                ),
119→                removeRecentItem: rxMethod<{
120→                    itemId: number;
121→                    playlistId: string;
122→                }>(
123→                    pipe(
124→                        switchMap(async ({ itemId, playlistId }) => {
125→                            await dbService.removeRecentItem(
126→                                itemId,
127→                                playlistId
128→                            );
129→                            // Reload recent items to update UI
130→                            const items =
131→                                await dbService.getRecentItems(playlistId);
132→                            patchState(store, {
133→                                recentItems: items.map((item) =>
134→                                    mapDbRecentItem(item, playlistId)
135→                                ),
136→                            });
137→                        })
