    id: string;
    name: string;
    serverUrl: string;
    username: string;
    password: string;
    type: string;
}

type XtreamDatabasePlaylistUpdate = {
    name?: string;
    username?: string;
    password?: string;
    serverUrl?: string;
    lastUpdated?: string;
};

type XtreamContentStream =
    | {
          category_id: string | number;
          rating?: string | number;
          rating_imdb?: string;
          last_modified?: string;
          added?: string;
          stream_icon?: string;
          poster?: string;
          cover?: string;
          name?: string;
          title?: string;
          series_id?: string | number;
          stream_id?: string | number;
      }
    | Record<string, unknown>;

export interface GlobalSearchResult extends XtreamContent {
    playlist_id: string;
    playlist_name: string;
}

export interface GlobalRecentItem extends XtreamContent {
    playlist_id: string;
    playlist_name: string;
    viewed_at: string;
}

export interface GlobalFavoriteItem extends XtreamContent {
    playlist_id: string;
    playlist_name: string;
    added_at: string;
}

@Injectable({
    providedIn: 'root',
})
export class DatabaseService {
