 44→function stalkerContentType(
 45→    fav: StalkerPortalItem
 46→): 'live' | 'movie' | 'series' {
 47→    if (fav.movie_id) return 'movie';
 48→    if (fav.series_id) return 'series';
 49→    if (
 50→        fav.stream_type === 'live' ||
 51→        fav.category_id === 'itv' ||
 52→        (fav.cmd && !fav.movie_id && !fav.series_id)
 53→    )
 54→        return 'live';
 55→    return 'live';
 56→}
