 64→@Injectable({ providedIn: 'root' })
 65→export class UnifiedFavoritesDataService {
 66→    private readonly store = inject(Store);
 67→    private readonly dbService = inject(DatabaseService);
 68→    private readonly playlistsService = inject(PlaylistsService);
 69→    private readonly translate = inject(TranslateService);
 70→
 71→    async getFavorites(
 72→        scope: CollectionScope,
 73→        playlistId?: string,
 74→        portalType?: string
 75→    ): Promise<UnifiedCollectionItem[]> {
 76→        if (scope === 'playlist' && playlistId) {
 77→            return this.getPlaylistFavorites(playlistId, portalType);
 78→        }
 79→        return this.getAllFavorites();
 80→    }
 81→
 82→    async removeFavorite(item: UnifiedCollectionItem): Promise<void> {
 83→        switch (item.sourceType) {
 84→            case 'm3u': {
 85→                const playlist = await firstValueFrom(
 86→                    this.playlistsService.getPlaylistById(item.playlistId)
 87→                );
 88→                const filtered = ((playlist.favorites as string[]) ?? [])
 89→                    .filter((f) => f !== item.streamUrl);
 90→                await firstValueFrom(
 91→                    this.playlistsService.setFavorites(item.playlistId, filtered)
 92→                );
 93→                break;
 94→            }
 95→            case 'xtream': {
 96→                if (window.electron && item.contentId != null) {
 97→                    await window.electron.dbRemoveFavorite(
 98→                        item.contentId,
 99→                        item.playlistId
100→                    );
101→                }
102→                break;
103→            }
104→            case 'stalker': {
105→                const sourceItemId = item.uid.split('::')[2];
106→                await firstValueFrom(
107→                    this.playlistsService.removeFromPortalFavorites(
108→                        item.playlistId,
109→                        sourceItemId
110→                    )
111→                );
112→                break;
113→            }
114→        }
115→    }
