117→    async reorder(items: UnifiedCollectionItem[]): Promise<void> {
118→        const uidOrder = items.map((i) => i.uid);
119→        const xtreamUpdates = items
120→            .filter((i) => i.sourceType === 'xtream' && i.contentId != null)
121→            .map((i, idx) => ({ content_id: i.contentId!, position: idx }));
122→
123→        await Promise.all([
124→            xtreamUpdates.length > 0 && window.electron
125→                ? window.electron.dbReorderGlobalFavorites(xtreamUpdates)
126→                : Promise.resolve(),
127→            this.saveOrder(uidOrder),
