133→    private async getAllFavorites(): Promise<UnifiedCollectionItem[]> {
134→        const [m3u, xtream, stalker, order] = await Promise.all([
135→            this.getM3uFavorites(),
136→            this.getXtreamAllFavorites(),
137→            this.getStalkerAllFavorites(),
138→            this.getSavedOrder(),
139→        ]);
