141→    }
142→
143→    private async getPlaylistFavorites(
144→        playlistId: string,
145→        portalType?: string
146→    ): Promise<UnifiedCollectionItem[]> {
147→        if (portalType === 'xtream') {
148→            return this.getXtreamPlaylistFavorites(playlistId);
149→        }
150→        if (portalType === 'stalker') {
151→            return this.getStalkerPlaylistFavorites(playlistId);
152→        }
153→        return this.getM3uPlaylistFavorites(playlistId);
154→    }
155→
156→    private async getM3uFavorites(): Promise<UnifiedCollectionItem[]> {
157→        const allMeta = await firstValueFrom(
158→            this.store.select(selectAllPlaylistsMeta)
159→                .pipe(map((m) => m as PlaylistMeta[]))
160→        );
161→        const results: UnifiedCollectionItem[] = [];
162→        for (const meta of allMeta.filter((p) => p._id && !p.serverUrl && !p.macAddress)) {
163→            results.push(...(await this.extractM3uFavorites(meta)));
164→        }
165→        return results;
166→    }
167→
168→    private async getM3uPlaylistFavorites(
169→        playlistId: string
170→    ): Promise<UnifiedCollectionItem[]> {
171→        const meta = await this.getPlaylistMeta(playlistId);
172→        if (!meta) return [];
173→        return this.extractM3uFavorites(meta);
174→    }
175→
176→    private async extractM3uFavorites(
177→        meta: PlaylistMeta
178→    ): Promise<UnifiedCollectionItem[]> {
179→        if (!meta.favorites?.length) return [];
180→        const favIds = new Set((meta.favorites as string[]).map(String));
181→        let playlist: PlaylistWithChannels | undefined;
182→        try {
183→            playlist = (await firstValueFrom(
184→                this.playlistsService.getPlaylistById(meta._id)
185→            )) as PlaylistWithChannels | undefined;
186→        } catch {
187→            return [];
188→        }
189→        return (playlist?.playlist?.items ?? [])
190→            .filter((ch) => favIds.has(ch.id) || favIds.has(ch.url))
191→            .map((ch) => ({
192→                uid: buildCollectionUid('m3u', meta._id, ch.url || ch.id),
193→                name: ch.name,
194→                contentType: 'live' as const,
195→                sourceType: 'm3u' as const,
196→                playlistId: meta._id,
197→                playlistName: meta.title || meta.filename || 'M3U',
198→                logo: ch.tvg?.logo ?? null,
199→                streamUrl: ch.url,
200→                tvgId: ch.tvg?.id || ch.tvg?.name || ch.name,
201→                addedAt: new Date(0).toISOString(),
202→                position: 0,
203→            }));
204→    }
205→
206→    private async getXtreamAllFavorites(): Promise<UnifiedCollectionItem[]> {
207→        if (!window.electron?.dbGetAllGlobalFavorites) return [];
208→        try {
209→            const rows = (await this.dbService.getAllGlobalFavorites()) as XtreamFavoriteRow[];
210→            return rows.map((r) => this.mapXtreamRow(r));
211→        } catch {
212→            return [];
213→        }
214→    }
215→
216→    private async getXtreamPlaylistFavorites(
217→        playlistId: string
218→    ): Promise<UnifiedCollectionItem[]> {
219→        if (!window.electron) return [];
220→        try {
221→            const rows = await this.dbService.getFavorites(playlistId);
222→            const meta = await this.getPlaylistMeta(playlistId);
223→            return (rows as unknown as XtreamFavoriteRow[]).map((r) => ({
224→                ...this.mapXtreamRow(r),
225→                playlistId,
226→                playlistName: meta?.title || 'Xtream',
227→            }));
228→        } catch {
229→            return [];
230→        }
231→    }
232→
233→    private mapXtreamRow(row: XtreamFavoriteRow): UnifiedCollectionItem {
234→        return {
235→            uid: buildCollectionUid(
236→                'xtream',
237→                row.playlist_id,
238→                row.xtream_id
239→            ),
240→            name: row.title,
241→            contentType: xtreamContentType(row.type),
242→            sourceType: 'xtream',
243→            playlistId: row.playlist_id,
244→            playlistName: row.playlist_name ?? 'Xtream',
245→            logo: row.type === 'live' ? (row.poster_url ?? null) : null,
246→            posterUrl: row.type !== 'live' ? (row.poster_url ?? null) : null,
247→            xtreamId: row.xtream_id,
248→            tvgId: row.type === 'live' ? String(row.xtream_id) : undefined,
249→            rating: row.rating ?? undefined,
250→            addedAt: row.added_at ?? new Date(0).toISOString(),
251→            position: row.position ?? 0,
252→            contentId: row.id,
253→        };
254→    }
255→
256→    private async getStalkerAllFavorites(): Promise<UnifiedCollectionItem[]> {
257→        const allMeta = await firstValueFrom(
258→            this.store.select(selectAllPlaylistsMeta)
259→                .pipe(map((m) => m as PlaylistMeta[]))
260→        );
261→        const results: UnifiedCollectionItem[] = [];
262→        for (const meta of allMeta.filter((p) => p._id && p.macAddress)) {
263→            results.push(...(await this.extractStalkerFavorites(meta)));
264→        }
265→        return results;
