268→    private async getStalkerPlaylistFavorites(
269→        playlistId: string
270→    ): Promise<UnifiedCollectionItem[]> {
271→        const meta = await this.getPlaylistMeta(playlistId);
272→        if (!meta) return [];
273→        return this.extractStalkerFavorites(meta);
