    Channel,
    Playlist,
    PlaylistMeta,
    StalkerPortalItem,
} from 'shared-interfaces';
import {
    buildCollectionUid,
    CollectionScope,
    UnifiedCollectionItem,
} from './unified-collection-item.interface';

const GLOBAL_FAVORITES_ORDER_KEY = 'global-favorites-channel-order-v1';

interface XtreamFavoriteRow {
    readonly id: number;
    readonly playlist_id: string;
    readonly playlist_name: string;
    readonly xtream_id: number;
    readonly title: string;
    readonly type: string;
    readonly poster_url?: string | null;
    readonly rating?: string | null;
    readonly added_at?: string | null;
    readonly position?: number | null;
}

type PlaylistWithChannels = Playlist & {
    readonly playlist?: { readonly items?: Channel[] };
};

function isStalkerItem(
    v: string | StalkerPortalItem
): v is StalkerPortalItem {
    return typeof v !== 'string';
}

function stalkerContentType(
    fav: StalkerPortalItem
): 'live' | 'movie' | 'series' {
    if (fav.movie_id) return 'movie';
    if (fav.series_id) return 'series';
    if (
        fav.stream_type === 'live' ||
        fav.category_id === 'itv' ||
        (fav.cmd && !fav.movie_id && !fav.series_id)
    )
        return 'live';
    return 'live';
}

function xtreamContentType(type: string): 'live' | 'movie' | 'series' {
    if (type === 'movie' || type === 'movies') return 'movie';
    if (type === 'series') return 'series';
    return 'live';
}

@Injectable({ providedIn: 'root' })
export class UnifiedFavoritesDataService {
    private readonly store = inject(Store);
