:host {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.global-favorites-page {
    display: flex;
    flex-direction: column;
    height: 100%;
    overflow: hidden;
}

.loading-state {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    flex: 1;
}

// ─── Grid layouts ──────────────────────────────────────────────────────────────

// With embedded player: sidebar | video-player
//                       sidebar | epg
.itv-container {
    display: grid;
    grid-template-columns: auto 1fr 1fr;
    grid-template-rows: minmax(0, 1fr) minmax(0, 1fr);
    grid-template-areas:
        'sidebar video-player video-player'
        'sidebar epg epg';
    height: 100%;
}

// With external player (MPV/VLC): sidebar | epg full height
.itv-container--external {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: 1fr;
    grid-template-areas: 'sidebar epg';
    height: 100%;

    .epg {
        border-top: none;
    }
}

// Without player: full-width sidebar + center prompt
.itv-container-no-player {
    display: grid;
    grid-template-columns: auto 1fr;
    grid-template-rows: 1fr;
    grid-template-areas: 'sidebar main';
    height: 100%;
}

// ─── Sidebar ───────────────────────────────────────────────────────────────────

.sidebar {
    grid-area: sidebar;
    width: 360px;
    min-width: 250px;
    max-width: 600px;
    flex-shrink: 0;
    position: relative;
    border-right: 1px solid var(--mat-sys-outline-variant);
    display: flex;
    flex-direction: column;
    overflow: hidden;
}

.sidebar-header {
    padding: 14px 16px 6px;
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    gap: 2px;
    border-bottom: 1px solid var(--mat-sys-outline-variant);
}

.sidebar-title {
    font-size: 15px;
    font-weight: 600;
    color: var(--mat-sys-on-surface);
    line-height: 1.3;
}

.sidebar-subtitle {
    font-size: 11px;
    color: var(--mat-sys-on-surface-variant);
    opacity: 0.8;
}

// ─── Video player ──────────────────────────────────────────────────────────────

.video-player {
    grid-area: video-player;
    min-height: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.player-toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 4px 12px 4px 16px;
    flex-shrink: 0;
    background: var(--mat-sys-surface-container-low);
    border-bottom: 1px solid var(--mat-sys-outline-variant);
    min-height: 40px;
}

.player-title {
    flex: 1;
    min-width: 0;
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    color: var(--mat-sys-on-surface);
}

.close-btn {
    flex-shrink: 0;
}

.video-player > app-vjs-player,
.video-player > app-html-video-player,
.video-player > app-art-player {
    flex: 1;
    min-height: 0;
    display: block;
}

// ─── EPG panel ─────────────────────────────────────────────────────────────────

.epg {
    grid-area: epg;
    min-height: 0;
    overflow: hidden;
    border-top: 1px solid var(--mat-sys-outline-variant);
    display: flex;
    flex-direction: column;
}

.epg-content {
    flex: 1;
    min-height: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
}

.epg-content > app-epg-view {
    flex: 1;
    min-height: 0;
}

// ─── No channel selected ───────────────────────────────────────────────────────

.no-channel-selected {
    grid-area: main;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 12px;
    color: var(--mat-sys-on-surface-variant);
    opacity: 0.6;
    font-size: 14px;

    mat-icon {
        font-size: 48px;
        width: 48px;
        height: 48px;
    }

    p {
        margin: 0;
    }
}

