input.content:
@if (isLoading()) {
    <div class="loading-state">
        <mat-spinner diameter="40" />
    </div>
} @else {
    <div class="collection-header">
        <span class="collection-title">{{ title() | translate }}</span>
        <mat-button-toggle-group
            class="scope-toggle"
            [value]="scope()"
            (change)="onScopeChange($event.value)"
            hideSingleSelectionIndicator
        >
            <mat-button-toggle value="playlist">
                <mat-icon>playlist_play</mat-icon>
                <span class="toggle-label">{{
                    'PORTALS.THIS_PLAYLIST' | translate
                }}</span>
            </mat-button-toggle>
            <mat-button-toggle value="all">
                <mat-icon>public</mat-icon>
                <span class="toggle-label">{{
                    'PORTALS.ALL_PLAYLISTS' | translate
                }}</span>
            </mat-button-toggle>
        </mat-button-toggle-group>
    </div>

    @if (showTabs()) {
        <mat-tab-group animationDuration="0" class="content-tabs">
            @if (hasLive()) {
                <mat-tab [label]="'PORTALS.LIVE_TV' | translate">
                    <app-unified-live-tab
                        [items]="liveItems()"
                        [mode]="mode()"
                        (removeItem)="onRemoveItem($event)"
                        (reorderItems)="onReorder($event)"
                    />
                </mat-tab>
            }
            @if (hasMovies()) {
                <mat-tab [label]="'PORTALS.MOVIES' | translate">
                    <app-unified-grid-tab
                        [items]="movieItems()"
                        [mode]="mode()"
                        [contentType]="'movie'"
                        (removeItem)="onRemoveItem($event)"
                    />
                </mat-tab>
            }
            @if (hasSeries()) {
                <mat-tab [label]="'PORTALS.SERIES' | translate">
                    <app-unified-grid-tab
                        [items]="seriesItems()"
                        [mode]="mode()"
                        [contentType]="'series'"
                        (removeItem)="onRemoveItem($event)"
                    />
                </mat-tab>
            }
        </mat-tab-group>
    } @else {
        @if (hasLive()) {
            <app-unified-live-tab
                [items]="liveItems()"
                [mode]="mode()"
                (removeItem)="onRemoveItem($event)"
                (reorderItems)="onReorder($event)"
            />
        }
        @if (hasMovies()) {
            <app-unified-grid-tab
                [items]="movieItems()"
                [mode]="mode()"
                [contentType]="'movie'"
                (removeItem)="onRemoveItem($event)"
            />
        }
        @if (hasSeries()) {
            <app-unified-grid-tab
                [items]="seriesItems()"
                [mode]="mode()"
                [contentType]="'series'"
                (removeItem)="onRemoveItem($event)"
            />
        }
        @if (!hasLive() && !hasMovies() && !hasSeries()) {
            <div class="empty-state">
                <mat-icon class="empty-icon">{{
                    mode() === 'favorites' ? 'favorite_border' : 'history'
                }}</mat-icon>
                <p class="empty-title">
                    {{
                        (mode() === 'favorites'
                            ? 'PORTALS.NO_FAVORITES'
                            : 'PORTALS.NO_RECENT_ITEMS'
                        ) | translate
                    }}
                </p>
            </div>
        }
    }
}

