@if (showImportOverlay()) {
    <app-loading-overlay
        [current]="getImportCount()"
        [total]="itemsToImport()"
    />
}

<div class="xtream-container">
    @if (!isWorkspaceLayout) {
        <app-navigation
            class="navigation-sidebar"
            [portalStatus]="portalStatus()"
            [selectedContentType]="selectedSection()"
        />
    }
    <router-outlet />
</div>

export function createXtreamRoutes(): Route[] {
    return [
        {
            path: 'xtreams/:id',
            loadComponent: loadXtreamShellComponent,
            children: [
                {
                    path: '',
                    redirectTo: 'vod',
                    pathMatch: 'full',
                },
                {
                    path: 'live',
                    loadComponent: loadLiveStreamLayoutComponent,
                    children: [
                        {
                            path: ':categoryId',
                            loadComponent: loadLiveStreamLayoutComponent,
                        },
                    ],
                },
                {
                    path: 'vod',
                    providers: provideXtreamCatalogFacade(),
                    loadComponent: loadXtreamMainContainerComponent,
                    children: [
                        {
                            path: '',
                            loadComponent: loadCategoryContentViewComponent,
                        },
                        {
                            path: ':categoryId',
                            loadComponent: loadCategoryContentViewComponent,
                        },
                        {
                            path: ':categoryId/:vodId',
                            loadComponent: loadVodDetailsRouteComponent,
                        },
                    ],
                },
                {
                    path: 'series',
                    providers: provideXtreamCatalogFacade(),
                    loadComponent: loadXtreamMainContainerComponent,
                    children: [
                        {
                            path: '',
                            loadComponent: loadCategoryContentViewComponent,
                        },
                        {
                            path: ':categoryId',
                            loadComponent: loadCategoryContentViewComponent,
                        },
                        {
                            path: ':categoryId/:serialId',
                            loadComponent: loadSerialDetailsComponent,
                        },
                    ],
                },
                {
                    path: 'favorites',
                    loadComponent: loadUnifiedCollectionComponent,
                    data: { mode: 'favorites', portalType: 'xtream' },
                },
                {
                    path: 'recent',
                    loadComponent: loadUnifiedCollectionComponent,
                    data: { mode: 'recent', portalType: 'xtream' },
                },
                {
                    path: 'search',
                    loadComponent: loadSearchResultsComponent,
                },
                {
                    path: 'recently-added',
                    loadComponent: loadRecentlyAddedComponent,
                },
                {
                    path: 'downloads',
                    loadComponent: loadDownloadsComponent,
                },
            ],
        },
    ];
}

