// ─── Card base ───────────────────────────────────────────────────────────────
mat-card {
    overflow: hidden;
    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease;
    box-shadow: none;
    background: transparent;
}

mat-card:hover {
    transform: translateY(-3px);
    box-shadow:
        0 8px 24px rgba(0, 0, 0, 0.35),
        0 2px 8px rgba(0, 0, 0, 0.2);
}

// ─── Grid layout ─────────────────────────────────────────────────────────────
.grid {
    mat-card {
        cursor: pointer;
        width: 100%;

        mat-card-content {
            padding: 0;
            margin: 0;
        }

        .card-thumbnail-container {
            position: relative;
            width: 100%;
            border-radius: 10px;
            overflow: hidden;
            aspect-ratio: 2 / 3; // maintain poster ratio
            background: var(--mat-sys-surface-container-high);
        }

        .stream-icon {
            width: 100%;
            height: 100%;
            object-fit: cover;
            border-radius: 10px;
            display: block;
            // No hardcoded light bg — uses parent container bg
            background: transparent;
        }

        .stream-icon-placeholder {
            width: 100%;
            height: 100%;
            min-height: 200px;
            // Use graphite surface token, not hardcoded grey
            background: var(--mat-sys-surface-container-high);
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            gap: 8px;
            color: var(--app-muted-color, var(--mat-sys-on-surface-variant));
