 495→    constructor() {
 496→        this.destroyRef.onDestroy(() => {
 497→            if (this.searchDebounceTimeoutId !== null) {
 498→                clearTimeout(this.searchDebounceTimeoutId);
 499→                this.searchDebounceTimeoutId = null;
 500→            }
 501→
 502→            document.removeEventListener('keydown', this.onDocumentKeydown);
 503→        });
 504→
 505→        document.addEventListener('keydown', this.onDocumentKeydown);
 506→
 507→        this.router.events
 508→            .pipe(
 509→                filter(
 510→                    (event): event is NavigationEnd =>
 511→                        event instanceof NavigationEnd
 512→                ),
 513→                takeUntilDestroyed()
 514→            )
 515→            .subscribe((event) => {
 516→                this.currentUrl.set(event.urlAfterRedirects);
 517→                this.syncSearchFromRoute();
 518→            });
 519→
 520→        this.syncSearchFromRoute();
 521→
 522→        effect(() => {
 523→            const context = this.currentContext();
 524→            const section = this.currentSection();
 525→            const term = this.appliedSearchQuery();
 526→
 527→            if (!context || context.provider !== 'xtreams') {
 528→                return;
 529→            }
 530→
 531→            if (section === 'search') {
 532→                this.xtreamStore.setSearchTerm(term);
 533→                return;
 534→            }
 535→
 536→            if (section === 'vod' || section === 'series') {
 537→                this.xtreamStore.setCategorySearchTerm(term);
 538→            }
 539→        });
 540→
 541→        effect(() => {
 542→            const context = this.currentContext();
 543→            const section = this.currentSection();
 544→            const term = this.appliedSearchQuery();
 545→
 546→            if (context?.provider === 'stalker' && section === 'search') {
 547→                this.syncStalkerSearchQueryParam(term);
 548→            }
 549→        });
 550→
 551→        effect(() => {
 552→            const context = this.currentContext();
 553→            const section = this.currentSection();
 554→            const useQuerySearch =
 555→                this.isSourcesRoute() ||
 556→                this.usesRouteQuerySearch(context, section);
 557→
 558→            if (!useQuerySearch) {
 559→                return;
 560→            }
 561→
 562→            this.syncSearchQueryParam(this.appliedSearchQuery());
 563→        });
 564→
 565→        effect(() => {
 566→            const context = this.currentContext();
 567→            if (!context || context.provider !== 'playlists') {
 568→                return;
 569→            }
 570→
 571→            this.lastM3uPlaylistId.set(context.playlistId);
 572→        });
 573→    }
