 927→        if (context?.provider === 'xtreams') {
 928→            if (section === 'search') {
 929→                const queryTerm = this.getRouteQueryParam('q');
 930→                this.setSearchState(queryTerm || this.xtreamStore.searchTerm());
 931→                return;
 932→            }
 933→            if (section === 'vod' || section === 'series') {
 934→                this.setSearchState(this.xtreamStore.categorySearchTerm());
 935→                return;
 936→            }
 937→        }
 938→
 939→        if (context?.provider === 'stalker' && section === 'search') {
 940→            this.setSearchState(this.getRouteQueryParam('q'));
 941→            return;
 942→        }
 943→
 944→        if (
 945→            this.isSourcesRoute() ||
 946→            this.usesRouteQuerySearch(context, section)
 947→        ) {
 948→            this.setSearchState(this.getRouteQueryParam('q'));
 949→            return;
 950→        }
 951→
