 995→    private syncStalkerSearchQueryParam(term: string): void {
 996→        const nextTerm = term.trim();
 997→        const currentTerm = this.getRouteQueryParam('q');
 998→
 999→        if (nextTerm === currentTerm) {
1000→            return;
1001→        }
1002→
1003→        this.syncSearchQueryParam(nextTerm);
1004→    }
