1006→    private syncSearchQueryParam(term: string): void {
1007→        const nextTerm = term.trim();
1008→        const currentTerm = this.getRouteQueryParam('q');
1009→        if (nextTerm === currentTerm) {
1010→            return;
1011→        }
1012→
1013→        const routePath = this.currentUrl().split('?')[0];
1014→        const queryParams = {
1015→            ...this.router.parseUrl(this.currentUrl()).queryParams,
1016→        };
1017→
1018→        if (nextTerm.length > 0) {
1019→            queryParams['q'] = nextTerm;
1020→        } else {
1021→            delete queryParams['q'];
1022→        }
1023→
1024→        const queryString = this.toQueryString(queryParams);
1025→        const nextUrl = queryString ? `${routePath}?${queryString}` : routePath;
1026→        this.router.navigateByUrl(nextUrl, { replaceUrl: true });
1027→    }
